import{d as E,C as u,o as K,c as v,j as i,a as e,E as a,a3 as d,k as o}from"./chunks/framework.Q4yG9rk_.js";const L=JSON.parse('{"title":"庄子·天下","description":"从古之道术的整体图景与百家分裂入手，辨析诸家保存的一端、实践得失及其限度，首先细读墨家与宋钘、尹文的救世方向。","frontmatter":{"title":"庄子·天下","description":"从古之道术的整体图景与百家分裂入手，辨析诸家保存的一端、实践得失及其限度，首先细读墨家与宋钘、尹文的救世方向。","category":"庄子精读","aliases":["天下","庄子天下","庄子·天下精读"],"source":["《庄子·杂篇·天下》","用户提供的原文与分段整理材料"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-33.md","filePath":"daoism/zhuang-zi/chapter-33.md","lastUpdated":1792641266000}'),B={name:"daoism/zhuang-zi/chapter-33.md"},J=E({...B,setup(G){const x=[{id:"tx1-zhifangshu",term:"治方术",pinyin:"",meaning:"从事、研习各种学说与方法；“治”不是治理这些方法。"},{id:"tx1-youwei",term:"其有为",pinyin:"",meaning:"自己所实行、所成就的学说与实践。"},{id:"tx1-bukejia",term:"不可加",pinyin:"",meaning:"不能再增加、超越，自认为已经足够高明。"},{id:"tx1-daoshu",term:"道术",pinyin:"",meaning:"本篇所追问的整体之道及其实践，不只指一种技能。"},{id:"tx1-wuhu",term:"恶乎",pinyin:"wū hū",meaning:"在哪里。“恶”为疑问词。"},{id:"tx1-shen",term:"神",pinyin:"shén",meaning:"「神何由降？」与「明何由出」对举，指神妙难测的一面。"},{id:"tx1-ming2",term:"明",pinyin:"míng",meaning:"「明何由出？」指明察、显明的一面。"},{id:"tx1-yuanyuyi",term:"原于一",pinyin:"",meaning:"根源于一、统一的根本；“一”不必限定为可计数的单一实体。"},{id:"tx1-zong",term:"宗",pinyin:"",meaning:"根本、宗本。"},{id:"tx1-jing",term:"精",pinyin:"",meaning:"精粹、精微的根本，具体义界须结合上下文。"},{id:"tx1-zhen",term:"真",pinyin:"",meaning:"真实、不失其本然，与造作失真相对。"},{id:"tx1-zhaobianhua",term:"兆于变化",pinyin:"",meaning:"显现、发端于变化等，“兆”的具体解释有差异。"},{id:"tx1-xunran",term:"熏然",pinyin:"",meaning:"温和、和暖的样子。"},{id:"tx1-fafen",term:"法为分",pinyin:"",meaning:"以法度确定区分与职分。"},{id:"tx1-mingbiao",term:"名为表",pinyin:"",meaning:"以名称标明身份、职事等。"},{id:"tx1-canyan",term:"参为验",pinyin:"",meaning:"通过参核、比较来检验。"},{id:"tx1-jijue",term:"稽为决",pinyin:"",meaning:"通过考核、查考作出裁定。"},{id:"tx1-shu",term:"数",pinyin:"",meaning:"方法、条理、制度或具体术数；不同句中侧重未必相同。"},{id:"tx1-xiangchi",term:"相齿",pinyin:"",meaning:"按此排列、相互衔接，联系百官的秩序理解。"},{id:"tx1-fanxi",term:"蕃息畜藏",pinyin:"",meaning:"生养繁衍、积蓄储藏；“畜”联系蓄积理解。"},{id:"tx1-youyiyang",term:"皆有以养",pinyin:"",meaning:"都有赖以获得养护、生计的条件。"},{id:"tx1-peishenming",term:"配神明",pinyin:"",meaning:"与神明相配、相应。"},{id:"tx1-chuntiandi",term:"醇天地",pinyin:"",meaning:"与天地相合、使之醇和等，不按酿酒义直译。"},{id:"tx1-benshu",term:"本数",pinyin:"běn shù",meaning:"根本的度数、条理。「明于本数」。"},{id:"tx1-modu",term:"末度",pinyin:"mò dù",meaning:"末节的度数。「系于末度」，与本数对举。"},{id:"tx1-liutong",term:"六通四辟",pinyin:"",meaning:"六方通达、四面开辟，突出无所壅塞的广大范围。"},{id:"tx1-zoulu",term:"邹鲁",pinyin:"",meaning:"邹、鲁地区，语境中联系儒学与典籍传承。"},{id:"tx1-jinshen",term:"缙绅先生",pinyin:"缙绅：jìn shēn",meaning:"有学问、具士人身份的先生。"},{id:"tx1-daozhi",term:"道志",pinyin:"道：dǎo",meaning:"表达、述说志与事等；此处“道”作动词，不是各句都在命名一个实体。"},{id:"tx1-zhongguo",term:"中国",pinyin:"",meaning:"当时的中原诸国、文化政治地域，不等同于现代国家概念。"},{id:"tx1-yicha",term:"一察",pinyin:"",meaning:"某一方面的察知、见解。"},{id:"tx1-zihao",term:"自好",pinyin:"",meaning:"自赏、自满于自己所得。"},{id:"tx1-bugaibubian",term:"不该不遍",pinyin:"",meaning:"不能包举、不能周遍。"},{id:"tx1-yiqu",term:"一曲之士",pinyin:"",meaning:"只通达一隅、一端的人；“曲”联系局部理解。"},{id:"tx1-pan",term:"判",pinyin:"pàn",meaning:"分割、割裂。「判天地之美」。"},{id:"tx1-xi",term:"析",pinyin:"xī",meaning:"剖析。「析万物之理」，与判并举。"},{id:"tx1-chaguren",term:"察古人之全",pinyin:"",meaning:"疑难语句；上下文涉及古人整体被分察、割裂的状态，具体字义有不同读法。"},{id:"tx1-chenshenming",term:"称神明之容",pinyin:"称：chèn",meaning:"与神明的广大相称；“容”联系容纳、规模等理解。"},{id:"tx1-neishengwaiwang",term:"内圣外王",pinyin:"",meaning:"内在圣德与外在治理的关联，不直接等同于后世某一种固定理论。"},{id:"tx1-ziweifang",term:"自为方",pinyin:"",meaning:"自立一套方法、方向或学说。"},{id:"tx1-wangbufan",term:"往而不反",pinyin:"",meaning:"各沿一端展开，却不返回整体；“反”通“返”，不等于机械复刻古代制度。"},{id:"tx1-tiandichun",term:"天地之纯",pinyin:"",meaning:"天地的纯全、未被割裂的整体。"},{id:"tx1-dati",term:"古人之大体",pinyin:"",meaning:"古人之道的整体规模与主要结构。"},{id:"tx2-buchi",term:"不侈于后世",pinyin:"",meaning:"不以奢侈夸示、遗留后世等，具体句义有解释空间。"},{id:"tx2-bumi",term:"不靡于万物",pinyin:"",meaning:"不耗费、糜费物用。"},{id:"tx2-buhui",term:"不晖于数度",pinyin:"",meaning:"不以制度仪节的华美炫耀等，“晖”联系光耀理解。"},{id:"tx2-shengmo",term:"绳墨自矫",pinyin:"",meaning:"用如绳墨般的准则约束、矫正自己。"},{id:"tx2-beiji",term:"备世之急",pinyin:"",meaning:"为世间急难作准备、救助。"},{id:"tx2-modi",term:"墨翟",pinyin:"mò dí",meaning:"墨子。"},{id:"tx2-qinguli",term:"禽滑厘",pinyin:"qín gǔ lí",meaning:"墨家人物，传统多视为墨子弟子。"},{id:"tx2-yuezhi",term:"说之",pinyin:"说：yuè",meaning:"喜悦、认同；“说”通“悦”。"},{id:"tx2-daguodashun",term:"为之大过，已之大顺",pinyin:"",meaning:"文字、句义有讨论空间；结合上下文涉及所行的过度及其方向，不强定唯一译文。"},{id:"tx2-feiyue",term:"非乐",pinyin:"",meaning:"反对耗费性的音乐活动与制度，不直接等同于反对一切声音。"},{id:"tx2-siwufu",term:"死不服",pinyin:"",meaning:"不采用相应丧服制度，不是遗体不穿衣服。"},{id:"tx2-fanaijianli",term:"泛爱兼利",pinyin:"",meaning:"广泛爱人，使人共同得利。"},{id:"tx2-buyi",term:"不异",pinyin:"",meaning:"本句与前后如何衔接有解释空间，不在此强定为完整的学派主张。"},{id:"tx2-guyue",term:"辟雍之乐",pinyin:"",meaning:"本段列举《咸池》《大章》《大韶》《大夏》《大濩》《武》等及辟雍之乐，作为古代礼乐的对照；不据此展开各乐起源的历史核验。"},{id:"tx2-guanguo",term:"棺椁",pinyin:"guān guǒ",meaning:"棺与棺外的套棺；层数是本篇叙述的礼制对照，不在此作历史制度校勘。"},{id:"tx2-fashi",term:"法式",pinyin:"",meaning:"作为规范、范式。"},{id:"tx2-weibai",term:"未败墨子道",pinyin:"",meaning:"疑难语句，与前后批评的衔接有不同理解，本次不以此强定整段褒贬。"},{id:"tx2-feige",term:"歌而非歌，哭而非哭，乐而非乐",pinyin:"",meaning:"“非”联系非议、否定理解，以歌、哭、乐及对它们的否定形成对照。"},{id:"tx2-dahu",term:"大觳",pinyin:"觳：hú",meaning:"过于刻薄、严苛，联系生活规范的苛苦理解。"},{id:"tx2-ren",term:"任",pinyin:"",meaning:"承担、承受。"},{id:"tx2-yinhongshui",term:"湮洪水",pinyin:"",meaning:"联系治理、平治洪水理解；具体字义须结合后文决江河等叙述。"},{id:"tx2-tuosi",term:"橐耜",pinyin:"tuó sì",meaning:"治土、挖土所用器具，具体器名解释有差异。"},{id:"tx2-jiuza",term:"九杂",pinyin:"",meaning:"疑难词，联系疏治、汇通天下河川理解。"},{id:"tx2-jing",term:"胫",pinyin:"jìng",meaning:"小腿。「胫无毛」，与「腓无跋」并列写劳形。"},{id:"tx2-feiwuba",term:"腓无跋",pinyin:"",meaning:"描写腿部劳损，具体字义有争议，不强定逐字解释。"},{id:"tx2-muyuzhifeng",term:"沐甚雨，栉疾风",pinyin:"栉：zhì",meaning:"以大雨为沐浴，以疾风为梳理，形容冒风雨劳作。"},{id:"tx2-qiuhe",term:"裘褐",pinyin:"",meaning:"皮衣与粗布衣，语境中突出简朴生活。"},{id:"tx2-jijue",term:"屐蹻",pinyin:"jī jué",meaning:"简陋鞋履，“蹻”的器物解释有差异。"},{id:"tx2-ziku",term:"自苦为极",pinyin:"",meaning:"以使自己劳苦作为极高准则。"},{id:"tx2-xiangliqin",term:"相里勤",pinyin:"xiàng lǐ qín",meaning:"墨家后学之一。「相里勤之弟子」。"},{id:"tx2-wuhou",term:"五侯之徒",pinyin:"wǔ hóu zhī tú",meaning:"与相里勤之弟子、南方墨者并列，写墨家后学的分化。"},{id:"tx2-beijue",term:"倍谲不同",pinyin:"",meaning:"涉及后学背离、解释分歧的疑难表述，结合相谓别墨的下文阅读。"},{id:"tx2-biemo",term:"别墨",pinyin:"",meaning:"与己不同的墨家派别，带有相互排斥意味。"},{id:"tx2-zi",term:"訾",pinyin:"zǐ",meaning:"非议、诋毁。"},{id:"tx2-buwu",term:"不仵",pinyin:"仵：wǔ",meaning:"不合、不相应。"},{id:"tx2-juzi",term:"巨子",pinyin:"",meaning:"墨家领袖。"},{id:"tx2-shi",term:"尸",pinyin:"",meaning:"主持、主其事，不作尸体解。"},{id:"tx2-luanzhi",term:"乱之上也，治之下也",pinyin:"",meaning:"疑难评语，具体训释有差异；不据此强定一句现代译文。"},{id:"tx2-tianxiahao",term:"墨子真天下之好也",pinyin:"",meaning:"在批评实践之后，对墨子爱天下、为天下用力的方向给予高度肯定；具体字句仍须结合上下文。"},{id:"tx2-buzhi",term:"不忮于众",pinyin:"忮：zhì",meaning:"不嫉害、伤害众人。"},{id:"tx2-bizu",term:"毕足而止",pinyin:"",meaning:"人己养生所需都满足后便停止，不再过求。"},{id:"tx2-baixin",term:"白心",pinyin:"",meaning:"使心明白、清洁，或表明心意等，具体解释有差异。"},{id:"tx2-songyin",term:"宋钘、尹文",pinyin:"",meaning:"本段评议的两位思想人物；不在此补定其完整生平与学派归属。"},{id:"tx2-huashanguan",term:"华山之冠",pinyin:"",meaning:"本段所说用以自表的冠式，具体形制不在此补写。"},{id:"tx2-bieyou",term:"别宥",pinyin:"",meaning:"重要疑难词，常联系辨别与宽容、解除蔽限等理解。"},{id:"tx2-er",term:"聏",pinyin:"ér",meaning:"常联系调和、和柔理解。"},{id:"tx2-qingyuzhi",term:"请欲置之以为主",pinyin:"",meaning:"具体句法及“之”的所指有讨论空间，结合前后调和、止争方向阅读。"},{id:"tx2-jianwuburu",term:"见侮不辱",pinyin:"",meaning:"受侮而不将其认成必须报复的羞辱；不直接用来否认实际损害。"},{id:"tx2-jingong",term:"禁攻寝兵",pinyin:"",meaning:"禁止攻伐，止息战争。"},{id:"tx2-shangshuo",term:"上说下教",pinyin:"",meaning:"对上游说，对下教导；此处“说”联系劝说、游说，不同于前文说通悦。"},{id:"tx2-qiangguo",term:"强聒",pinyin:"聒：guō",meaning:"反复劝说，即使不被接受也不停止。"},{id:"tx2-qiangjian",term:"上下见厌而强见",pinyin:"",meaning:"上下都已厌弃，却仍坚持求见、出现或劝说；具体字义有解释空间。"},{id:"tx2-wusheng",term:"五升之饭",pinyin:"",meaning:"本段关于食量的表述；不未经考察换算为固定现代饭量。"},{id:"tx2-tuao",term:"图傲乎救世之士哉",pinyin:"",meaning:"疑难句，“图傲”的文字与训释有讨论空间，不强定逐字译文。"},{id:"tx2-kecha",term:"苛察",pinyin:"",meaning:"苛细地察责、挑剔。"},{id:"tx2-jiawu",term:"不以身假物",pinyin:"",meaning:"不让自身受外物借用、役使等，具体解释有差异。"},{id:"tx2-mingburuji",term:"明之不如己也",pinyin:"",meaning:"涉及以是否有益天下衡量他人的明智，具体语法与范围须保留解释空间。"},{id:"tx2-guaqian",term:"情欲寡浅",pinyin:"",meaning:"将欲求限制在少而浅的范围。"},{id:"tx2-shizhi",term:"适至是而止",pinyin:"",meaning:"恰到这一范围便止，标明其所行的限度。"},{id:"tx3-gongdang",term:"公而不党，易而无私",pinyin:"",meaning:"公正而不偏党，平易而无私；具体字义仍须放在应物方向中理解。"},{id:"tx3-wuzhu",term:"决然无主",pinyin:"",meaning:"不以固定的私己主张作主等；不直接解释为完全没有判断与行动根据。"},{id:"tx3-quwu",term:"趣物而不两",pinyin:"",meaning:"疑难表述，通常联系趋应事物而不立对待、分歧等理解，不强定唯一译法。"},{id:"tx3-wuze",term:"于物无择",pinyin:"",meaning:"不以私己好恶选择、排斥事物，与之俱往。"},{id:"tx3-pengtianshen",term:"彭蒙、田骈、慎到",pinyin:"",meaning:"本段合评的三位人物；其历史学说不直接由本篇评语概括为全部。"},{id:"tx3-qiwanwu",term:"齐万物",pinyin:"",meaning:"将万物平等看待、不以一端偏取为首；不等于抹去所有实际差别。"},{id:"tx3-baobian",term:"包之而不能辩之",pinyin:"",meaning:"大道包容万物，不以分别取舍穷尽万物等；“辩”的具体义项有解释空间。"},{id:"tx3-xuanjiao",term:"选则不遍，教则不至",pinyin:"",meaning:"选择会遗漏、固定教法未必周到的警惕；不直接作为取消所有选择与教育的原则。"},{id:"tx3-qizhi",term:"弃知去己",pinyin:"",meaning:"舍弃智虑与自我执持；本段继续检验这种做法是否走向无知之物。"},{id:"tx3-budeyi",term:"缘不得已",pinyin:"",meaning:"依循不得不如此的条件，不以己意强作。"},{id:"tx3-lingtai",term:"泠汰于物",pinyin:"",meaning:"疑难词组，常联系淡漠、疏放地对物理解，保留字义差异。"},{id:"tx3-zhibuzhi",term:"知不知，将薄知而后邻伤之者也",pinyin:"",meaning:"字义与句法疑难，涉及智虑及其伤累的批评，不强拼成唯一译文。"},{id:"tx3-xike",term:"謑髁无任",pinyin:"",meaning:"疑难表述，常联系不受拘束、不任事的姿态理解，不强定读音与逐字译法。"},{id:"tx3-zongtuo",term:"纵脱无行",pinyin:"",meaning:"放纵脱略、不拘固定行迹等，具体语义须结合批评尚贤大圣的上下文。"},{id:"tx3-zhuipai",term:"椎拍輐断",pinyin:"",meaning:"疑难词组，常联系浑圆、随转、不守棱角理解；不据此建立精确动作描述。"},{id:"tx3-sheshifei",term:"舍是与非，苟可以免",pinyin:"",meaning:"舍弃是非判断，只求能够免患；本篇在此检验其随转方式的限度。"},{id:"tx3-weiran",term:"魏然",pinyin:"",meaning:"具体训释有差异，结合不师知虑、推曳而行的状态理解。"},{id:"tx3-moshi",term:"若磨石之隧",pinyin:"",meaning:"以磨石随动等作譬喻，“隧”的具体字义有讨论空间。"},{id:"tx3-jianji",term:"建己",pinyin:"",meaning:"树立、执持自我，进而形成患累。"},{id:"tx3-kuai",term:"块",pinyin:"",meaning:"土块等无知之物，在本段中成为不失道、却非生人之行的对照。"},{id:"tx3-haojie",term:"豪桀",pinyin:"",meaning:"豪杰；其讥评是本段所引人物话语，应与篇末总评区分。"},{id:"tx3-shengren",term:"非生人之行，而至死人之理",pinyin:"",meaning:"批评其无知随转不能成为活人的实践；不直接当成慎到全部历史学说的定义。"},{id:"tx3-bujiao",term:"得不教",pinyin:"",meaning:"学得不以教法强制等的方向，具体句义保留讨论空间。"},{id:"tx3-yinran",term:"窨然",pinyin:"",meaning:"疑难词，常联系幽深、沉默等理解，不强定读音。"},{id:"tx3-fanren",term:"常反人，不见观",pinyin:"",meaning:"涉及与众人相反、未被理解或观照等的表述，具体句义有差异。"},{id:"tx3-wanduan",term:"魭断",pinyin:"",meaning:"与前文輐断等相关的疑难用字，保留随转、混同及其局限的解释空间。"},{id:"tx3-wei",term:"韪",pinyin:"wěi",meaning:"是、正确；“所言之韪”指所宣称的是。"},{id:"tx3-gaihu",term:"概乎皆尝有闻",pinyin:"",meaning:"大体说来都曾听闻道术的一端，保留其真实所得。"},{id:"tx3-benjing",term:"以本为精，以物为粗",pinyin:"",meaning:"以根本为精要，以具体物为较粗的展开；不据此否定万物价值。"},{id:"tx3-youji",term:"以有积为不足",pinyin:"",meaning:"将占有、积聚看作不足的表现等，具体“积”所指有解释空间。"},{id:"tx3-danran",term:"澹然",pinyin:"",meaning:"恬淡、不躁求的样子。"},{id:"tx3-guanlao",term:"关尹、老聃",pinyin:"",meaning:"本段合评人物；不在此补定生平、著作归属及历史关系。"},{id:"tx3-changwuyou",term:"常无有",pinyin:"",meaning:"涉及无、有及常的根本表达，具体句读与义界不强定。"},{id:"tx3-taiyi",term:"太一",pinyin:"",meaning:"广大、统一的根本等，不直接定为一个可计数实体。"},{id:"tx3-ruruo",term:"濡弱谦下",pinyin:"",meaning:"柔弱、谦下的外在姿态，不应仅按表演性的示弱理解。"},{id:"tx3-kongxu",term:"空虚不毁万物",pinyin:"",meaning:"不以自我执持充塞，不毁伤万物；是本段所强调的实际内容。"},{id:"tx3-wuju",term:"在己无居",pinyin:"",meaning:"自身不固守一个占据的位置、成见等，不直接解释为没有居所。"},{id:"tx3-xingwu",term:"形物自著",pinyin:"",meaning:"事物形态、实情自行显现等，具体句法有解释空间。"},{id:"tx3-dongruoshui",term:"其动若水",pinyin:"qí dòng ruò shuǐ",meaning:"动时如水，写应物而不滞。"},{id:"tx3-jingruojing",term:"其静若镜",pinyin:"qí jìng ruò jìng",meaning:"静时如镜，写照见而不藏。"},{id:"tx3-yingruoxiang",term:"其应若响",pinyin:"qí yìng ruò xiǎng",meaning:"应时如回响，写随感而应。"},{id:"tx3-wuhu",term:"芴乎若亡",pinyin:"",meaning:"恍惚、若无的状态；不按实际消失直译。"},{id:"tx3-detong",term:"同焉者和，得焉者失",pinyin:"",meaning:"涉及相应、和合与执得、失去的对照，具体义项不强定。"},{id:"tx3-zhiqixiong",term:"知其雄",pinyin:"zhī qí xióng",meaning:"知道什么是雄强。「知其雄，守其雌」，写守的一面。"},{id:"tx3-shouqici",term:"守其雌",pinyin:"shǒu qí cí",meaning:"守持柔雌的一面，与「知其雄」成对。"},{id:"tx3-gou",term:"垢",pinyin:"",meaning:"污垢、卑下或不受欢迎的负担等，结合处后谦下理解。"},{id:"tx3-wucang",term:"无藏也故有余",pinyin:"",meaning:"不以占藏为务，反而有余；不直接承诺现实中不储备便永不匮乏。"},{id:"tx3-kuiran",term:"岿然",pinyin:"kuī rán",meaning:"高大、安定独立的样子。"},{id:"tx3-xubufei",term:"徐而不费",pinyin:"",meaning:"舒缓而不耗费，联系行动不躁进、不自耗。"},{id:"tx3-wuwei",term:"无为也而笑巧",pinyin:"",meaning:"不以强作、机巧为主，批评刻意经营；不一概等同于不做事。"},{id:"tx3-ququan",term:"曲全",pinyin:"",meaning:"曲处而保全等，不强定为一套屈从求利的技巧。"},{id:"tx3-jiu",term:"咎",pinyin:"",meaning:"过失、祸患。"},{id:"tx3-shenyue",term:"以深为根，以约为纪",pinyin:"",meaning:"以深厚为根本，以简约为纲纪；不把约直接等同于贫乏。"},{id:"tx3-buxiao",term:"不削于人",pinyin:"",meaning:"不侵削、损害他人。"},{id:"tx3-weizhiji",term:"虽未至于极",pinyin:"",meaning:"在高度赞许中仍明确保留未达极致的界限，不能略去。"},{id:"tx4-jimo",term:"寂漠",pinyin:"",meaning:"寂静、淡漠，联系不显露固定形迹理解。"},{id:"tx4-wuxing",term:"无形",pinyin:"",meaning:"没有可以固定把握的形态。"},{id:"tx4-wuchang",term:"变化无常",pinyin:"",meaning:"变化没有恒定不变的具体样式，不等于毫无条理。"},{id:"tx4-yu",term:"与",pinyin:"yú",meaning:"前几句作疑问语气词，近于“欤”。"},{id:"tx4-manghu",term:"芒乎",pinyin:"máng hū",meaning:"恍惚不明的样子。「芒乎何之」。"},{id:"tx4-huhu",term:"忽乎",pinyin:"hū hū",meaning:"倏忽不定的样子。「忽乎何适」。"},{id:"tx4-hezhi",term:"何之",pinyin:"hé zhī",meaning:"往哪里去。「芒乎何之」。"},{id:"tx4-heshi",term:"何适",pinyin:"hé shì",meaning:"到哪里去。「忽乎何适」，与何之并举。"},{id:"tx4-biluo",term:"毕罗",pinyin:"",meaning:"全部罗列、呈现。"},{id:"tx4-gui",term:"莫足以归",pinyin:"",meaning:"没有某个具体事物足以作为最终归着，具体句义有解释空间。"},{id:"tx4-miuyou",term:"谬悠",pinyin:"",meaning:"悠远、超出通常尺度，不直接译为错误百出。"},{id:"tx4-huangtang",term:"荒唐",pinyin:"",meaning:"广远、漫无边际等，不直接等同于现代荒谬可笑义。"},{id:"tx4-wuduanya",term:"无端崖",pinyin:"",meaning:"没有固定端绪与边际。"},{id:"tx4-zizong",term:"恣纵",pinyin:"",meaning:"自由展开，不拘常格。"},{id:"tx4-butang",term:"不傥，不奇见之也",pinyin:"",meaning:"疑难语句，常联系不偏执一端、不以奇异自炫理解。"},{id:"tx4-chenzhuo",term:"沈浊",pinyin:"",meaning:"沉浊、混浊，语境中评价天下的状态。"},{id:"tx4-zhuangyu",term:"庄语",pinyin:"",meaning:"庄重、正面而严整的言说，不是“庄周说的话”。"},{id:"tx4-zhiyan",term:"卮言",pinyin:"zhī yán",meaning:"常联系随变化而调整、不固着于一端的言说理解。"},{id:"tx4-manyan",term:"曼衍",pinyin:"",meaning:"绵延、铺展、自由伸展。"},{id:"tx4-zhongyan",term:"重言",pinyin:"",meaning:"借受尊重者、前人或有分量的话来立言，不简单解释为重复的话。"},{id:"tx4-weizhen",term:"为真",pinyin:"",meaning:"使言说显得真实、可信、有分量等，不等于权威之言必然正确。"},{id:"tx4-yuyan",term:"寓言",pinyin:"",meaning:"寄托于他者、人物与故事的言说，不只限于现代寓言文体。"},{id:"tx4-aoni",term:"敖倪",pinyin:"ào nì",meaning:"傲视、轻慢；“敖”联系“傲”理解。"},{id:"tx4-qianshifei",term:"谴是非",pinyin:"",meaning:"以是非责斥、谴责等，不直接等于取消所有判断。"},{id:"tx4-huanwei",term:"环玮",pinyin:"",meaning:"奇伟、瑰奇等，形容其书不同常格。"},{id:"tx4-lianhuan",term:"连犿",pinyin:"",meaning:"疑难词，常联系宛转、随转、圆融等理解，不强定读音。"},{id:"tx4-chugui",term:"諔诡",pinyin:"chù guǐ",meaning:"奇异、诡特。"},{id:"tx4-buyiyi",term:"不可以已",pinyin:"",meaning:"不能停止，或不能尽其表达。"},{id:"tx4-zaowu",term:"造物者",pinyin:"",meaning:"造化、生成万物的作用，不必理解为人格化造物神。"},{id:"tx4-waisisheng",term:"外死生",pinyin:"",meaning:"不以死生分别作为束缚、将其置于执持之外，不是否认死亡事实。"},{id:"tx4-wuzhongshi",term:"无终始者",pinyin:"",meaning:"不受固定终始所限者，具体所指有解释空间。"},{id:"tx4-pihongsi",term:"弘大而辟",pinyin:"",meaning:"开阔、广大、舒展。"},{id:"tx4-choushi",term:"稠适而上遂",pinyin:"",meaning:"疑难词组，整体含有契合根本、向上通达的赞许意味。"},{id:"tx4-yinghua",term:"应于化",pinyin:"",meaning:"回应、顺应变化。"},{id:"tx4-jiewu",term:"解于物",pinyin:"",meaning:"对物通解、从物的拘系中解脱等，有不同解释。"},{id:"tx4-butui",term:"其来不蜕",pinyin:"",meaning:"疑难语句，不强定“蜕”的唯一义项及整句译法。"},{id:"tx4-weijin",term:"未之尽",pinyin:"",meaning:"尚未穷尽它，或其展开尚不可穷尽等；也有着重保留未究竟之意的读法，不简单定为不足判语。"},{id:"tx5-duofang",term:"多方",pinyin:"",meaning:"学说、方法与才智涉及多方面，不等于整体已经完备。"},{id:"tx5-wuche",term:"其书五车",pinyin:"",meaning:"用书籍数量突出学问丰厚，不在此作实际藏书量核验。"},{id:"tx5-chuanbo",term:"舛驳",pinyin:"chuǎn bó",meaning:"错杂、乖异或不相贯通，属于本篇的评价。"},{id:"tx5-buzhong",term:"不中",pinyin:"",meaning:"不合宜、不切中等，不未经论证便解释为每个命题都形式错误。"},{id:"tx5-liwu",term:"历物之意",pinyin:"",meaning:"分别考察、论说万物的见解等。"},{id:"tx5-dayi",term:"大一",pinyin:"dà yī",meaning:"「至大无外，谓之大一」，指无所不包的整体。"},{id:"tx5-xiaoyi",term:"小一",pinyin:"xiǎo yī",meaning:"「至小无内，谓之小一」，与大一对举。"},{id:"tx5-wuhou",term:"无厚，不可积也，其大千里",pinyin:"",meaning:"涉及厚度与范围的命题；可帮助思考不同尺度，但原文未附证明，不强定为某个现代数学对象。"},{id:"tx5-fangni",term:"日方中方睨",pinyin:"",meaning:"太阳正在中天，也正在偏斜等，以变化中的同时表达构成反常命题；“睨”的具体解释有差异。"},{id:"tx5-xiaotongyi",term:"小同异",pinyin:"xiǎo tóng yì",meaning:"局部的同异。「大同而与小同异，此之谓小同异」。"},{id:"tx5-datongyi",term:"大同异",pinyin:"dà tóng yì",meaning:"整体的同异。「万物毕同毕异，此之谓大同异」。"},{id:"tx5-shiyue",term:"今日适越而昔来",pinyin:"",meaning:"涉及时间、往来与观察位置的疑难命题，不强定唯一解释。"},{id:"tx5-lianhuan",term:"连环可解",pinyin:"",meaning:"有关连环及可解性的反常命题；不在此擅补其证明方式。"},{id:"tx5-zhongyang",term:"天之中央",pinyin:"",meaning:"涉及中心与位置的命题，原文未详述其论证，不作为实际地理定位。"},{id:"tx5-tiandiyiti",term:"泛爱万物，天地一体",pinyin:"",meaning:"将万物与天地联系为整体的主张；宣称一体并不免除实践与自宁的检验。"},{id:"tx5-xiaobian",term:"晓辩者",pinyin:"",meaning:"使辩者知晓、向辩者阐明等，具体句义有讨论空间。"},{id:"tx5-bianzhemingti",term:"卵有毛",pinyin:"",meaning:"本段列出的辩者命题，涉及名实、属性、数量、关系等；未逐条提供论证，不强制合成一套系统。"},{id:"tx5-dingzi",term:"丁子",pinyin:"",meaning:"疑难名词，不在此强定为某种具体动物或器物。"},{id:"tx5-nian",term:"蹍",pinyin:"",meaning:"践踏、接触地面等，具体义项须结合“轮不蹍地”的命题阅读。"},{id:"tx5-zhizhi",term:"指不至，至不绝",pinyin:"",meaning:"涉及指、至及其关系的疑难命题，保留解释空间。"},{id:"tx5-zaorui",term:"凿不围枘",pinyin:"枘：ruì",meaning:"凿孔与榫头关系的命题；具体字义与论证未在原文展开。"},{id:"tx5-jing",term:"景",pinyin:"",meaning:"影子，“飞鸟之景”联系飞鸟之影理解。"},{id:"tx5-zushi",term:"镞矢",pinyin:"镞：zú",meaning:"箭镞、箭矢，语境中联系疾行的箭。"},{id:"tx5-huangma",term:"黄马骊牛三",pinyin:"",meaning:"涉及名称、属性与数量的命题，不直接以未经说明的计数方式定解。"},{id:"tx5-chui",term:"棰",pinyin:"chuí",meaning:"短杖、木棍；“日取其半”涉及不断取半的过程，不等于现实切割可无限执行。"},{id:"tx5-huantuan",term:"桓团、公孙龙",pinyin:"",meaning:"本段列举的辩者人物，不把全段所有命题无差别归为他们或惠施个人所创。"},{id:"tx5-shixin",term:"饰人之心，易人之意",pinyin:"",meaning:"修饰、改变人的心意等，属于对辩说作用的评议。"},{id:"tx5-you",term:"囿",pinyin:"yòu",meaning:"范围、限域；这里指出辩者受限于胜口而未能服心。"},{id:"tx5-di",term:"柢",pinyin:"dǐ",meaning:"根柢、所据的基础。"},{id:"tx5-cunxiong",term:"施存雄而无术",pinyin:"",meaning:"疑难表述，涉及惠施口谈与自我评价，保留字义、句法差异。"},{id:"tx5-yiren",term:"倚人",pinyin:"",meaning:"疑难称谓，常有奇异之人等读法，不擅作身份认定。"},{id:"tx5-huangliao",term:"黄缭",pinyin:"",meaning:"本段向惠施问天地、风雨雷霆之故的人物。"},{id:"tx5-fanren",term:"以反人为实",pinyin:"",meaning:"以与常人相反、异于他人的说法作为实质等；具体义界有解释空间。"},{id:"tx5-bushi",term:"与众不适",pinyin:"",meaning:"与众人不相适、不相合。"},{id:"tx5-qiangwu",term:"弱于德，强于物",pinyin:"",meaning:"在本篇评价中，精神与德的安顿不足，向万物的辨说却很强；不等于每个具体观察都无效。"},{id:"tx5-tuao",term:"其涂隩矣",pinyin:"",meaning:"其道路局促、深曲或受阻等，具体“隩”义有讨论空间。"},{id:"tx5-wenmeng",term:"一蚊一虻之劳",pinyin:"虻：méng",meaning:"以微小虫类的忙碌反衬从天地之道衡量时的局促，不是否认其才力存在。"},{id:"tx5-heyong",term:"何庸",pinyin:"",meaning:"有何用、何以用等，须结合整段评价理解。"},{id:"tx5-chongyi",term:"夫充一尚可，曰愈贵，道几矣",pinyin:"",meaning:"疑难句，涉及一端之学及其被抬高后的限度，不强定“几”的唯一读音与全句译法。"},{id:"tx5-zining",term:"自宁",pinyin:"",meaning:"使自身安定、安顿，不只是辩论暂时停止。"},{id:"tx5-taidang",term:"骀荡而不得",pinyin:"",meaning:"才力散漫流荡而未得其归处等，具体训释有差异。"},{id:"tx5-zhuwu",term:"逐万物而不反",pinyin:"",meaning:"不断向万物展开、追逐，却不返回根本与自身安顿，回扣总纲。"},{id:"tx5-qiongxiang",term:"穷响以声，形与影竞走",pinyin:"",meaning:"以声音追尽回响、形体与影子竞跑，表现所用办法使追逐难以止息。"}],m=[{id:"tx-p1-01",label:"诸家自足与道术之问",sentences:[["天下之",{text:"治方术",glossary:"tx1-zhifangshu"},"者多矣，皆以",{text:"其有为",glossary:"tx1-youwei"},{text:"不可加",glossary:"tx1-bukejia"},"矣！"],["古之所谓",{text:"道术",glossary:"tx1-daoshu"},"者，果",{text:"恶乎",glossary:"tx1-wuhu"},"在？曰：“无乎不在。”"],["曰：“",{text:"神",glossary:"tx1-shen"},"何由降？",{text:"明",glossary:"tx1-ming2"},"何由出？”“圣有所生，王有所成，皆",{text:"原于一",glossary:"tx1-yuanyuyi"},"。”"]]},{id:"tx-p1-02",label:"不离根本",sentences:[["不离于",{text:"宗",glossary:"tx1-zong"},"，谓之天人；不离于",{text:"精",glossary:"tx1-jing"},"，谓之神人；不离于",{text:"真",glossary:"tx1-zhen"},"，谓之至人。"]]},{id:"tx-p1-03",label:"圣人与君子",sentences:[["以天为宗，以德为本，以道为门，",{text:"兆于变化",glossary:"tx1-zhaobianhua"},"，谓之圣人；"],["以仁为恩，以义为理，以礼为行，以乐为和，",{text:"熏然",glossary:"tx1-xunran"},"慈仁，谓之君子；"]]},{id:"tx-p1-04",label:"百官的条理",sentences:[["以",{text:"法为分",glossary:"tx1-fafen"},"，以",{text:"名为表",glossary:"tx1-mingbiao"},"，以",{text:"参为验",glossary:"tx1-canyan"},"，以",{text:"稽为决",glossary:"tx1-jijue"},"，其",{text:"数",glossary:"tx1-shu"},"一二三四是也，百官以此",{text:"相齿",glossary:"tx1-xiangchi"},"；"]]},{id:"tx-p1-05",label:"民生与养护",sentences:[["以事为常，以衣食为主，",{text:"蕃息畜藏",glossary:"tx1-fanxi"},"，老弱孤寡为意，",{text:"皆有以养",glossary:"tx1-youyiyang"},"，民之理也。"]]},{id:"tx-p1-06",label:"古人之备",sentences:[["古之人其备乎！",{text:"配神明",glossary:"tx1-peishenming"},"，",{text:"醇天地",glossary:"tx1-chuntiandi"},"，育万物，和天下，泽及百姓，"],["明于",{text:"本数",glossary:"tx1-benshu"},"，系于",{text:"末度",glossary:"tx1-modu"},"，",{text:"六通四辟",glossary:"tx1-liutong"},"，小大精粗，其运无乎不在。"]]},{id:"tx-p1-07",label:"旧法与典籍传承",sentences:[["其明而在",{text:"数",glossary:"tx1-shu"},"度者，旧法、世传之史尚多有之；"],["其在于《诗》、《书》、《礼》、《乐》者，",{text:"邹鲁",glossary:"tx1-zoulu"},"之士、",{text:"缙绅先生",glossary:"tx1-jinshen"},"多能明之。"],["《诗》以",{text:"道志",glossary:"tx1-daozhi"},"，《书》以道事，《礼》以道行，《乐》以道和，《易》以道阴阳，《春秋》以道名分。"]]},{id:"tx-p1-08",label:"散布于百家",sentences:[["其",{text:"数",glossary:"tx1-shu"},"散于天下而设于",{text:"中国",glossary:"tx1-zhongguo"},"者，百家之学时或称而道之。"]]},{id:"tx-p1-09",label:"失序与一察自好",sentences:[["天下大乱，贤圣不明，道德不一。天下多得",{text:"一察",glossary:"tx1-yicha"},"焉以",{text:"自好",glossary:"tx1-zihao"},"。"]]},{id:"tx-p1-10",label:"各有长处而不周遍",sentences:[["譬如耳目鼻口，皆有所明，不能相通。犹百家众技也，皆有所长，时有所用。"],["虽然，",{text:"不该不遍",glossary:"tx1-bugaibubian"},"，",{text:"一曲之士",glossary:"tx1-yiqu"},"也。"]]},{id:"tx-p1-11",label:"整体被分察",sentences:[[{text:"判",glossary:"tx1-pan"},"天地之美，",{text:"析",glossary:"tx1-xi"},"万物之理，",{text:"察古人之全",glossary:"tx1-chaguren"},"。"],["寡能备于天地之美，",{text:"称神明之容",glossary:"tx1-chenshenming"},"。"]]},{id:"tx-p1-12",label:"内圣外王隐晦",sentences:[["是故",{text:"内圣外王",glossary:"tx1-neishengwaiwang"},"之道，暗而不明，郁而不发，天下之人各为其所欲焉以",{text:"自为方",glossary:"tx1-ziweifang"},"。"]]},{id:"tx-p1-13",label:"往而不反与道术之裂",sentences:[["悲夫！百家",{text:"往而不反",glossary:"tx1-wangbufan"},"，必不合矣！"],["后世之学者，不幸不见",{text:"天地之纯",glossary:"tx1-tiandichun"},"，",{text:"古人之大体",glossary:"tx1-dati"},"。道术将为天下裂。"]]},{id:"tx-p2-01",label:"墨家所承的道术方向",sentences:[[{text:"不侈于后世",glossary:"tx2-buchi"},"，",{text:"不靡于万物",glossary:"tx2-bumi"},"，",{text:"不晖于数度",glossary:"tx2-buhui"},"，以",{text:"绳墨自矫",glossary:"tx2-shengmo"},"，而",{text:"备世之急",glossary:"tx2-beiji"},"。"],["古之道术有在于是者，",{text:"墨翟",glossary:"tx2-modi"},"、",{text:"禽滑厘",glossary:"tx2-qinguli"},"闻其风而",{text:"说之",glossary:"tx2-yuezhi"},"。"]]},{id:"tx-p2-02",label:"节用与非乐",sentences:[[{text:"为之大过，已之大顺",glossary:"tx2-daguodashun"},"。作为《",{text:"非乐",glossary:"tx2-feiyue"},"》，命之曰《节用》。生不歌，死无服。"],["墨子",{text:"泛爱兼利",glossary:"tx2-fanaijianli"},"而非斗，其道不怒。又好学而博，",{text:"不异",glossary:"tx2-buyi"},"，不与先王同，毁古之礼乐。"]]},{id:"tx-p2-03",label:"古代礼乐的对照",sentences:[["黄帝有《咸池》，尧有《大章》，舜有《大韶》，禹有《大夏》，汤有《大濩》，文王有",{text:"辟雍之乐",glossary:"tx2-guyue"},"，武王、周公作《武》。"],["古之丧礼，贵贱有仪，上下有等。天子",{text:"棺椁",glossary:"tx2-guanguo"},"七重，诸侯五重，大夫三重，士再重。"]]},{id:"tx-p2-04",label:"薄葬成为法式",sentences:[["今墨子独生不歌，",{text:"死不服",glossary:"tx2-siwufu"},"，桐棺三寸而无椁，以为",{text:"法式",glossary:"tx2-fashi"},"。"],["以此教人，恐不爱人；以此自行，固不爱己。",{text:"未败墨子道",glossary:"tx2-weibai"},"。"]]},{id:"tx-p2-05",label:"情感与普遍承担",sentences:[["虽然，",{text:"歌而非歌，哭而非哭，乐而非乐",glossary:"tx2-feige"},"，是果类乎？"],["其生也勤，其死也薄，其道",{text:"大觳",glossary:"tx2-dahu"},"。使人忧，使人悲，其行难为也。"],["恐其不可以为圣人之道，反天下之心。天下不堪。墨子虽独能",{text:"任",glossary:"tx2-ren"},"，奈天下何！离于天下，其去王也远矣！"]]},{id:"tx-p2-06",label:"法禹与劳苦",sentences:[["墨子称道曰：“昔禹之",{text:"湮洪水",glossary:"tx2-yinhongshui"},"，决江河而通四夷九州也。名山三百，支川三千，小者无数。"],["禹亲自操",{text:"橐耜",glossary:"tx2-tuosi"},"而",{text:"九杂",glossary:"tx2-jiuza"},"天下之川。",{text:"腓无跋",glossary:"tx2-feiwuba"},"，",{text:"胫",glossary:"tx2-jing"},"无毛，",{text:"沐甚雨，栉疾风",glossary:"tx2-muyuzhifeng"},"，置万国。禹大圣也，而形劳天下也如此。”"]]},{id:"tx-p2-07",label:"自苦成为准入标准",sentences:[["使后世之墨者，多以",{text:"裘褐",glossary:"tx2-qiuhe"},"为衣，以",{text:"屐蹻",glossary:"tx2-jijue"},"为服，日夜不休，以",{text:"自苦为极",glossary:"tx2-ziku"},"，曰：“不能如此，非禹之道也，不足谓墨。”"]]},{id:"tx-p2-08",label:"后学分歧",sentences:[[{text:"相里勤",glossary:"tx2-xiangliqin"},"之弟子，",{text:"五侯之徒",glossary:"tx2-wuhou"},"，南方之墨者若获、已齿、邓陵子之属，俱诵《墨经》，而",{text:"倍谲不同",glossary:"tx2-beijue"},"，相谓",{text:"别墨",glossary:"tx2-biemo"},"。"],["以坚白同异之辩相",{text:"訾",glossary:"tx2-zi"},"，以奇偶",{text:"不仵",glossary:"tx2-buwu"},"之辞相应，以",{text:"巨子",glossary:"tx2-juzi"},"为圣人。"],["皆愿为之",{text:"尸",glossary:"tx2-shi"},"，冀得为其后世，至今不决。"]]},{id:"tx-p2-09",label:"墨家之意与行",sentences:[["墨翟、禽滑厘之意则是，其行则非也。将使后世之墨者，必以自苦",{text:"腓无跋",glossary:"tx2-feiwuba"},"、胫无毛相进而已矣。"],[{text:"乱之上也，治之下也",glossary:"tx2-luanzhi"},"。"],["虽然，",{text:"墨子真天下之好也",glossary:"tx2-tianxiahao"},"，将求之不得也，虽枯槁不舍也，才士也夫！"]]},{id:"tx-p2-10",label:"宋尹所承的道术方向",sentences:[["不累于俗，不饰于物，不苟于人，",{text:"不忮于众",glossary:"tx2-buzhi"},"，愿天下之安宁以活民命，人我之养，",{text:"毕足而止",glossary:"tx2-bizu"},"，以此",{text:"白心",glossary:"tx2-baixin"},"。"],["古之道术有在于是者，",{text:"宋钘、尹文",glossary:"tx2-songyin"},"闻其风而悦之。"]]},{id:"tx-p2-11",label:"别宥与心之行",sentences:[["作为",{text:"华山之冠",glossary:"tx2-huashanguan"},"以自表，接万物以",{text:"别宥",glossary:"tx2-bieyou"},"为始。语心之容，命之曰“心之行”。"],["以",{text:"聏",glossary:"tx2-er"},"合欢，以调海内。",{text:"请欲置之以为主",glossary:"tx2-qingyuzhi"},"。"]]},{id:"tx-p2-12",label:"止争与强说",sentences:[[{text:"见侮不辱",glossary:"tx2-jianwuburu"},"，救民之斗，",{text:"禁攻寝兵",glossary:"tx2-jingong"},"，救世之战。"],["以此周行天下，",{text:"上说下教",glossary:"tx2-shangshuo"},"。虽天下不取，",{text:"强聒",glossary:"tx2-qiangguo"},"而不舍者也。"],["故曰：",{text:"上下见厌而强见",glossary:"tx2-qiangjian"},"也。"]]},{id:"tx-p2-13",label:"为人与自养失衡",sentences:[["虽然，其为人太多，其自为太少，曰：“请欲固置",{text:"五升之饭",glossary:"tx2-wusheng"},"足矣。”"],["先生恐不得饱，弟子虽饥，不忘天下，日夜不休。曰：“我必得活哉！”",{text:"图傲乎救世之士哉",glossary:"tx2-tuao"},"！"]]},{id:"tx-p2-14",label:"所倡界限与自我评价",sentences:[["曰：“君子不为",{text:"苛察",glossary:"tx2-kecha"},"，",{text:"不以身假物",glossary:"tx2-jiawu"},"。”"],["以为无益于天下者，",{text:"明之不如己也",glossary:"tx2-mingburuji"},"。"]]},{id:"tx-p2-15",label:"内外方向与所行限度",sentences:[["以",{text:"禁攻寝兵",glossary:"tx2-jingong"},"为外，以",{text:"情欲寡浅",glossary:"tx2-guaqian"},"为内。其小大精粗，其行",{text:"适至是而止",glossary:"tx2-shizhi"},"。"]]},{id:"tx-p3-01",label:"公而无私、与物俱往",sentences:[[{text:"公而不党，易而无私",glossary:"tx3-gongdang"},"，",{text:"决然无主",glossary:"tx3-wuzhu"},"，",{text:"趣物而不两",glossary:"tx3-quwu"},"，不顾于虑，不谋于知，",{text:"于物无择",glossary:"tx3-wuze"},"，与之俱往。"],["古之道术有在于是者，",{text:"彭蒙、田骈、慎到",glossary:"tx3-pengtianshen"},"闻其风而悦之。"]]},{id:"tx-p3-02",label:"齐物与无遗",sentences:[[{text:"齐万物",glossary:"tx3-qiwanwu"},"以为首，曰：“天能覆之而不能载之，地能载之而不能覆之，大道能",{text:"包之而不能辩之",glossary:"tx3-baobian"},"。”"],["知万物皆有所可，有所不可。故曰：“",{text:"选则不遍，教则不至",glossary:"tx3-xuanjiao"},"，道则无遗者矣。”"]]},{id:"tx-p3-03",label:"弃知去己与不得已",sentences:[["是故慎到",{text:"弃知去己",glossary:"tx3-qizhi"},"，而",{text:"缘不得已",glossary:"tx3-budeyi"},"。",{text:"泠汰于物",glossary:"tx3-lingtai"},"，以为道理。"],["曰：“",{text:"知不知，将薄知而后邻伤之者也",glossary:"tx3-zhibuzhi"},"。”"]]},{id:"tx-p3-04",label:"免患与随转",sentences:[[{text:"謑髁无任",glossary:"tx3-xike"},"，而笑天下之尚贤也；",{text:"纵脱无行",glossary:"tx3-zongtuo"},"，而非天下之大圣；",{text:"椎拍輐断",glossary:"tx3-zhuipai"},"，与物宛转；",{text:"舍是与非，苟可以免",glossary:"tx3-sheshifei"},"。"],["不师知虑，不知前后，",{text:"魏然",glossary:"tx3-weiran"},"而已矣。推而后行，曳而后往。"],["若飘风之还，若羽之旋，",{text:"若磨石之隧",glossary:"tx3-moshi"},"，全而无非，动静无过，未尝有罪。"]]},{id:"tx-p3-05",label:"无知之物与生人之行",sentences:[["是何故？夫无知之物，无",{text:"建己",glossary:"tx3-jianji"},"之患，无用知之累，动静不离于理，是以终身无誉。"],["故曰：“至于若无知之物而已，无用贤圣。夫",{text:"块",glossary:"tx3-kuai"},"不失道。”"],[{text:"豪桀",glossary:"tx3-haojie"},"相与笑之曰：“慎到之道，",{text:"非生人之行，而至死人之理",glossary:"tx3-shengren"},"。”适得怪焉。"]]},{id:"tx-p3-06",label:"彭蒙田骈与评议收束",sentences:[["田骈亦然，学于彭蒙，",{text:"得不教",glossary:"tx3-bujiao"},"焉。"],["彭蒙之师曰：“古之道人，至于莫之是、莫之非而已矣。其风",{text:"窨然",glossary:"tx3-yinran"},"，恶可而言。”"],[{text:"常反人，不见观",glossary:"tx3-fanren"},"，而不免于",{text:"魭断",glossary:"tx3-wanduan"},"。其所谓道非道，而所言之",{text:"韪",glossary:"tx3-wei"},"不免于非。"],["彭蒙、田骈、慎到不知道。虽然，",{text:"概乎皆尝有闻",glossary:"tx3-gaihu"},"者也。"]]},{id:"tx-p3-07",label:"关老所承的道术方向",sentences:[[{text:"以本为精，以物为粗",glossary:"tx3-benjing"},"，",{text:"以有积为不足",glossary:"tx3-youji"},"，",{text:"澹然",glossary:"tx3-danran"},"独与神明居。"],["古之道术有在于是者，",{text:"关尹、老聃",glossary:"tx3-guanlao"},"闻其风而悦之。"],["建之以",{text:"常无有",glossary:"tx3-changwuyou"},"，主之以",{text:"太一",glossary:"tx3-taiyi"},"。以",{text:"濡弱谦下",glossary:"tx3-ruruo"},"为表，以",{text:"空虚不毁万物",glossary:"tx3-kongxu"},"为实。"]]},{id:"tx-p3-08",label:"关尹：无居与应物",sentences:[["关尹曰：“",{text:"在己无居",glossary:"tx3-wuju"},"，",{text:"形物自著",glossary:"tx3-xingwu"},"。”",{text:"其动若水",glossary:"tx3-dongruoshui"},"，",{text:"其静若镜",glossary:"tx3-jingruojing"},"，",{text:"其应若响",glossary:"tx3-yingruoxiang"},"。"],[{text:"芴乎若亡",glossary:"tx3-wuhu"},"，寂乎若清。",{text:"同焉者和，得焉者失",glossary:"tx3-detong"},"。未尝先人而常随人。"]]},{id:"tx-p3-09",label:"老聃：守雌、处后与取虚",sentences:[["老聃曰：“",{text:"知其雄",glossary:"tx3-zhiqixiong"},"，",{text:"守其雌",glossary:"tx3-shouqici"},"，为天下溪；知其白，守其辱，为天下谷。”"],["人皆取先，己独取后。曰：“受天下之",{text:"垢",glossary:"tx3-gou"},"”。人皆取实，己独取虚。“",{text:"无藏也故有余",glossary:"tx3-wucang"},"”。",{text:"岿然",glossary:"tx3-kuiran"},"而有余。"]]},{id:"tx-p3-10",label:"徐而不费、宽容不削",sentences:[["其行身也，",{text:"徐而不费",glossary:"tx3-xubufei"},"，",{text:"无为也而笑巧",glossary:"tx3-wuwei"},"。人皆求福，己独",{text:"曲全",glossary:"tx3-ququan"},"。曰：“苟免于",{text:"咎",glossary:"tx3-jiu"},"”。"],[{text:"以深为根，以约为纪",glossary:"tx3-shenyue"},"。曰：“坚则毁矣，锐则挫矣”。常宽容于物，",{text:"不削于人",glossary:"tx3-buxiao"},"。"],[{text:"虽未至于极",glossary:"tx3-weizhiji"},"，关尹、老聃乎，古之博大真人哉！"]]},{id:"tx-p4-01",label:"无形与变化之问",sentences:[[{text:"寂漠",glossary:"tx4-jimo"},{text:"无形",glossary:"tx4-wuxing"},"，",{text:"变化无常",glossary:"tx4-wuchang"},"，死",{text:"与",glossary:"tx4-yu"},"？生与？天地并与？神明往与？"],[{text:"芒乎",glossary:"tx4-manghu"},{text:"何之",glossary:"tx4-hezhi"},"？",{text:"忽乎",glossary:"tx4-huhu"},{text:"何适",glossary:"tx4-heshi"},"？万物",{text:"毕罗",glossary:"tx4-biluo"},"，",{text:"莫足以归",glossary:"tx4-gui"},"。"],["古之道术有在于是者，庄周闻其风而悦之。"]]},{id:"tx-p4-02",label:"广远言说与天下处境",sentences:[["以",{text:"谬悠",glossary:"tx4-miuyou"},"之说，",{text:"荒唐",glossary:"tx4-huangtang"},"之言，",{text:"无端崖",glossary:"tx4-wuduanya"},"之辞，时",{text:"恣纵",glossary:"tx4-zizong"},"而",{text:"不傥，不奇见之也",glossary:"tx4-butang"},"。"],["以天下为",{text:"沈浊",glossary:"tx4-chenzhuo"},"，不可与",{text:"庄语",glossary:"tx4-zhuangyu"},"。"]]},{id:"tx-p4-03",label:"三言",sentences:[["以",{text:"卮言",glossary:"tx4-zhiyan"},"为",{text:"曼衍",glossary:"tx4-manyan"},"，以",{text:"重言",glossary:"tx4-zhongyan"},{text:"为真",glossary:"tx4-weizhen"},"，以",{text:"寓言",glossary:"tx4-yuyan"},"为广。"]]},{id:"tx-p4-04",label:"天地精神与世俗相处",sentences:[["独与天地精神往来，而不",{text:"敖倪",glossary:"tx4-aoni"},"于万物。不",{text:"谴是非",glossary:"tx4-qianshifei"},"，以与世俗处。"]]},{id:"tx-p4-05",label:"书辞与充实",sentences:[["其书虽",{text:"环玮",glossary:"tx4-huanwei"},"，而",{text:"连犿",glossary:"tx4-lianhuan"},"无伤也。其辞虽参差，而",{text:"諔诡",glossary:"tx4-chugui"},"可观。彼其充实，",{text:"不可以已",glossary:"tx4-buyiyi"},"。"]]},{id:"tx-p4-06",label:"造化与死生",sentences:[["上与",{text:"造物者",glossary:"tx4-zaowu"},"游，而下与",{text:"外死生",glossary:"tx4-waisisheng"},"、",{text:"无终始者",glossary:"tx4-wuzhongshi"},"为友。"]]},{id:"tx-p4-07",label:"本与宗",sentences:[["其于本也，",{text:"弘大而辟",glossary:"tx4-pihongsi"},"，深闳而肆；其于宗也，可谓",{text:"稠适而上遂",glossary:"tx4-choushi"},"矣。"]]},{id:"tx-p4-08",label:"应化解物与未尽",sentences:[["虽然，其",{text:"应于化",glossary:"tx4-yinghua"},"而",{text:"解于物",glossary:"tx4-jiewu"},"也，其理不竭，",{text:"其来不蜕",glossary:"tx4-butui"},"，芒乎昧乎，",{text:"未之尽",glossary:"tx4-weijin"},"者。"]]},{id:"tx-p5-01",label:"才学与总评",sentences:[["惠施",{text:"多方",glossary:"tx5-duofang"},"，",{text:"其书五车",glossary:"tx5-wuche"},"，其道",{text:"舛驳",glossary:"tx5-chuanbo"},"，其言也",{text:"不中",glossary:"tx5-buzhong"},"。"]]},{id:"tx-p5-02",label:"大小与形量",sentences:[[{text:"历物之意",glossary:"tx5-liwu"},"，曰：“至大无外，谓之",{text:"大一",glossary:"tx5-dayi"},"；至小无内，谓之",{text:"小一",glossary:"tx5-xiaoyi"},"。"],[{text:"无厚，不可积也，其大千里",glossary:"tx5-wuhou"},"。天与地卑，山与泽平。",{text:"日方中方睨",glossary:"tx5-fangni"},"，物方生方死。"]]},{id:"tx-p5-03",label:"同异与时空",sentences:[["大同而与",{text:"小同异",glossary:"tx5-xiaotongyi"},"，此之谓‘小同异’；万物毕同毕异，此之谓‘",{text:"大同异",glossary:"tx5-datongyi"},"’。"],["南方无穷而有穷。",{text:"今日适越而昔来",glossary:"tx5-shiyue"},"。",{text:"连环可解",glossary:"tx5-lianhuan"},"也。"],["我知",{text:"天之中央",glossary:"tx5-zhongyang"},"，燕之北、越之南是也。",{text:"泛爱万物，天地一体",glossary:"tx5-tiandiyiti"},"也。”"]]},{id:"tx-p5-04",label:"辩者相应",sentences:[["惠施以此为大，观于天下而",{text:"晓辩者",glossary:"tx5-xiaobian"},"，天下之辩者相与乐之。"],[{text:"卵有毛",glossary:"tx5-bianzhemingti"},"。鸡有三足。郢有天下。犬可以为羊。马有卵。",{text:"丁子",glossary:"tx5-dingzi"},"有尾。火不热。山出口。轮不",{text:"蹍",glossary:"tx5-nian"},"地。目不见。"],[{text:"指不至，至不绝",glossary:"tx5-zhizhi"},"。龟长于蛇。矩不方，规不可以为圆。",{text:"凿不围枘",glossary:"tx5-zaorui"},"。飞鸟之",{text:"景",glossary:"tx5-jing"},"未尝动也。"],[{text:"镞矢",glossary:"tx5-zushi"},"之疾，而有不行、不止之时。狗非犬。",{text:"黄马骊牛三",glossary:"tx5-huangma"},"。白狗黑。孤驹未尝有母。一尺之",{text:"棰",glossary:"tx5-chui"},"，日取其半，万世不竭。"],["辩者以此与惠施相应，终身无穷。"]]},{id:"tx-p5-05",label:"胜口而不服心",sentences:[[{text:"桓团、公孙龙",glossary:"tx5-huantuan"},"辩者之徒，",{text:"饰人之心，易人之意",glossary:"tx5-shixin"},"，能胜人之口，不能服人之心，辩者之",{text:"囿",glossary:"tx5-you"},"也。"],["惠施日以其知与之辩，特与天下之辩者为怪，此其",{text:"柢",glossary:"tx5-di"},"也。"]]},{id:"tx-p5-06",label:"自贤与遍说万物",sentences:[["然惠施之口谈，自以为最贤，曰：“天地其壮乎，",{text:"施存雄而无术",glossary:"tx5-cunxiong"},"。”"],["南方有",{text:"倚人",glossary:"tx5-yiren"},"焉，曰",{text:"黄缭",glossary:"tx5-huangliao"},"，问天地所以不坠不陷，风雨雷霆之故。"],["惠施不辞而应，不虑而对，遍为万物说。说而不休，多而无已，犹以为寡，益之以怪，",{text:"以反人为实",glossary:"tx5-fanren"},"，而欲以胜人为名，是以",{text:"与众不适",glossary:"tx5-bushi"},"也。"]]},{id:"tx-p5-07",label:"强物弱德与道路之限",sentences:[[{text:"弱于德，强于物",glossary:"tx5-qiangwu"},"，",{text:"其涂隩矣",glossary:"tx5-tuao"},"。"],["由天地之道观惠施之能，其犹",{text:"一蚊一虻之劳",glossary:"tx5-wenmeng"},"者也。其于物也",{text:"何庸",glossary:"tx5-heyong"},"！"],[{text:"夫充一尚可，曰愈贵，道几矣",glossary:"tx5-chongyi"},"！"]]},{id:"tx-p5-08",label:"不能自宁与往而不反",sentences:[["惠施不能以此",{text:"自宁",glossary:"tx5-zining"},"，散于万物而不厌，卒以善辩为名。"],["惜乎！惠施之才，",{text:"骀荡而不得",glossary:"tx5-taidang"},"，",{text:"逐万物而不反",glossary:"tx5-zhuwu"},"，是",{text:"穷响以声，形与影竞走",glossary:"tx5-qiongxiang"},"也，悲夫！"]]}],y=[{text:"圣有所生，王有所成，皆原于一。",guide:"一与无乎不在：共同根本与广泛展开相联系，道术不被某一处、某一家独占。",note:"不意味着所有学说都完全正确，也不强定“一”为某种实体。"},{text:"古之人其备乎！",guide:"备：不同层面相通：根本、精神、教化、制度与民生相接，不只是知识数量多。",note:"这是理想性的整体建构，不直接当成历史上已经完整实现的事实。"},{text:"明于本数，系于末度。",guide:"本数与末度：整体既包含根本条理，也包含具体法度，不以一方取代另一方。",note:"不据此补写完整制度体系或固定的本末清单。"},{text:"天下多得一察焉以自好。",guide:"一察与自好：局部所得并非全错，问题在把它提升为整体完备的凭据。",note:"专门研究不自动等于自满；专注一端与否认其他层面不同。"},{text:"皆有所长，时有所用。虽然，不该不遍。",guide:"有长而不遍：局部价值与局部限度同时保留。",note:"有用不等于完整，不完整也不等于无用。"},{text:"百家往而不反，必不合矣！",guide:"裂：往而不反：各沿一端自立，却失去回看共同根本与整体的能力。",note:"分裂不只是多样性；返回也不是恢复古代一切具体形式。"}],b=[{text:"皆以其有为不可加矣！",guide:"问题不只在诸家繁多，更在各以所得自足。",note:"局部成就何时被误当成整体完备？"},{text:"无乎不在。",guide:"道术的展开不被单一学派、制度或技能独占。",note:"共同根本与多种展开为什么并不冲突？"},{text:"老弱孤寡为意，皆有以养。",guide:"养民与日常生活被纳入整体，而非精神境界之外的附属。",note:"完整之道为什么必须面对具体生计与脆弱处境？"},{text:"其数散于天下。",guide:"不同地方保存道术的一端，尚不等于不能相通的分裂。",note:"多处传承与各端自足，有什么区别？"},{text:"皆有所长，时有所用。",guide:"先肯定诸家的实际所得，再限定其周遍性。",note:"为什么评价一端需要同时保留价值与限度？"},{text:"往而不反。",guide:"分析与展开之后，是否还能回看整体成为关键。",note:"返回整体为何不等于取消分析或复刻古制？"}],q=[{text:"古之道术有在于是者。",guide:"所承与所行：先承认节制、救急、安民与止战保存了古之道术的一端，再检验实践形态。",note:"本篇评议不是诸家完整的自我说明，也不是从开头全盘否定。"},{text:"墨子虽独能任，奈天下何！",guide:"个人承担与普遍法式：个人坚忍不自动成为要求天下人人同样承受的根据。",note:"不是一切节俭不爱人，批评在过度及其普遍推广。"},{text:"日夜不休，以自苦为极。",guide:"劳苦从代价变成资格：救灾中的劳苦被抽离为最高标准，并用来界定谁配称墨者。",note:"不否认禹的救灾，也不把所有艰苦承担视为错误。"},{text:"意则是，其行则非也。",guide:"墨家之意与行：用意、实践与人物评价分开，敬重墨子仍能批评其推广方式。",note:"不能简化为墨子全对或全错。"},{text:"强聒而不舍。",guide:"止争与应人分寸：救世坚持与不顾接受情境的强说并存。",note:"不是坚持本身无价值，也不是见侮便必须沉默受害。"},{text:"其为人太多，其自为太少。",guide:"养人与养己：安民方向本来包含人我足养，实践却可能损耗自身持续行动的条件。",note:"不将批评解释为不应帮助他人。"},{text:"其行适至是而止。",guide:"明确所得与明确限度：止战与寡欲有真实价值，但不能仅凭这组内外方向自称周遍。",note:"不因范围有限就否认其全部意义，也不认定已完整实现内圣外王。"}],c=[{text:"备世之急。",guide:"墨家先被放在节制物用、救助急难的道术方向中。",note:"值得承认的方向，与后来实践得失为什么需要分开？"},{text:"以此教人，恐不爱人。",guide:"爱人的用意可能在严苛的普遍法式中失去爱护。",note:"个人能承受，是否足以要求所有人照行？"},{text:"以自苦为极。",guide:"劳苦可能从解决问题的代价，变成独立的德行与资格标准。",note:"为何不能只以受苦程度衡量实践价值？"},{text:"意则是，其行则非也。",guide:"文本同时肯定用意与人物，批评具体实践。",note:"怎样敬重倡导者，又不免除其方法的检验？"},{text:"人我之养，毕足而止。",guide:"宋尹所承方向本来同时包含养人与养己。",note:"后面的自养不足为何不是无关紧要的小事？"},{text:"上下见厌而强见也。",guide:"不舍的坚持也须面对实际接受情境。",note:"继续劝说何时是坚持，何时需要改变方式？"},{text:"以禁攻寝兵为外，以情欲寡浅为内。",guide:"内外主张被明确概括，同时被限定范围。",note:"有一组内外安排，为何仍不等于整体周遍？"}],f=[{text:"于物无择，与之俱往。",guide:"去己与随物：承认不以私己偏取、排斥万物的道术方向。",note:"并不自动证明后来所有随转方式都合宜。"},{text:"非生人之行，而至死人之理。",guide:"无知之物的限度：本段检验去己是否被推成取消活人判断与行动的无知随转。",note:"这是所引批评及篇内评议，不概括为慎到完整的历史思想。"},{text:"虽然，概乎皆尝有闻者也。",guide:"有所闻与不知道：严厉批评之外，仍承认三人听闻了道术的一端。",note:"不把总评压成全无所得。"},{text:"以濡弱谦下为表，以空虚不毁万物为实。",guide:"表与实：柔下的呈现需要不毁物的实际内容，不只是示弱姿态。",note:"不能仅靠谦弱外貌证明修养。"},{text:"其动若水，其静若镜，其应若响。",guide:"无居而应：不固守己见，与具体事物相应。",note:"不简单等同于被推曳才行动。"},{text:"虽未至于极……古之博大真人哉！",guide:"博大与未极：高度赞许宽容不削，同时保留整体尺度。",note:"不忽略未极，也不把它误读成否定全部所得。"}],k=[{text:"选则不遍。",guide:"选择可能遗漏，所承方向是避免以一端排除整体。",note:"如何保留这一警惕，而不取消必要辨别？"},{text:"推而后行，曳而后往。",guide:"去己在此被推向类似无知之物的随转。",note:"不强作与失去活人的应对能力是否相同？"},{text:"皆尝有闻者也。",guide:"最终批评仍保留真实所得。",note:"为什么严厉总评也不能省略这个转折？"},{text:"空虚不毁万物。",guide:"关老的空虚以不毁物作为实质。",note:"外在谦弱与实际不伤人应怎样分别检验？"},{text:"其应若响。",guide:"不先立己，与物相应而非只求免患。",note:"应物与机械随转的关键差别是什么？"},{text:"虽未至于极。",guide:"赞许不取消整体之道的更大尺度。",note:"承认博大与承认未极为什么可以并存？"}],P=[{text:"寂漠无形，变化无常。",guide:"无形而应化：不被固定形态拘住，与变化相接。",note:"不是一切无条理，也不把开头问句转成已证命题。"},{text:"以卮言为曼衍，以重言为真，以寓言为广。",guide:"三言与表达位置：随化伸展、借重立言、寄言他者，改变内容与读者相遇的方式。",note:"不把卮言当任意摇摆、重言当权威保证、寓言压成单一寓意。"},{text:"独与天地精神往来，而不敖倪于万物。",guide:"精神广大而不傲物：精神的独特不转成轻慢具体万物的资格。",note:"不以超越世俗为拒绝他人的凭据。"},{text:"连犿无伤……諔诡可观……彼其充实。",guide:"奇异而有实质：书辞的自由仍以无伤、可观与充实接受评价。",note:"不是奇异本身足够，也不保证文字完全没有批评锋芒。"},{text:"弘大而辟，深闳而肆。",guide:"本宗与应物：评价不只在文学形式，而涉及根本通达与应化解物。",note:"不改造成固定境界等级。"},{text:"芒乎昧乎，未之尽者。",guide:"未尽的开放：保留难尽、未尽与评议限度的解释空间。",note:"不等同于关老的未至于极，也不宣布庄周已被确认为最终完整之道。"}],z=[{text:"死与？生与？",guide:"连续问句松开匆忙定论，而非暗中保证某个答案。",note:"哪些死生、宇宙命题原文并未证明？"},{text:"不可与庄语。",guide:"非常规表达被放在天下沈浊的沟通处境中。",note:"内容之外，听取方式是否也需要改变？"},{text:"卮言、重言、寓言。",guide:"不同表达位置相配合，而非只给一个结论增添装饰。",note:"读者怎样在不同人物与情境中理解问题？"},{text:"不敖倪于万物。",guide:"精神广大与不轻慢具体事物必须连读。",note:"通达根本为何不能成为傲物的许可证？"},{text:"其应于化而解于物也。",guide:"通本的评价再次回到变化与具体万物。",note:"为什么不能只将此段读成文学才能的赞美？"},{text:"未之尽者。",guide:"高评价并未被封闭成无疑的最终定案。",note:"怎样同时保留赞许力度与解释边界？"}],w=[{text:"惠施多方，其书五车。",guide:"多方与不周遍：才学丰厚被承认，却不自动证明道术整体已通。",note:"不把书多当成完整，也不因总评严厉否认所有观察价值。"},{text:"历物之意。",guide:"命题与论证：反常命题挑战惯常分类、尺度与观察位置。",note:"原文大多只列命题，不强补唯一论证，也不全部归于惠施。"},{text:"能胜人之口，不能服人之心。",guide:"胜口与服心：辩论取胜与理解、认可和精神安顿不同。",note:"服心也不保证命题真实，不将情感认可替代证据。"},{text:"而欲以胜人为名。",guide:"以胜人为名：知识展开可能转为求异、求胜与自贤。",note:"不把所有辩论、创新与反常观点都视为争名。"},{text:"散于万物而不厌。",guide:"不能自宁：外向辨说不断增长，却不能替代自身与根本的安顿。",note:"不是要求停止研究万物。"},{text:"逐万物而不反。",guide:"往而不反：篇末将个人追逐回扣百家各沿一端不返回的总纲。",note:"返回不等于复古或反对一切分析。"}],T=[{text:"其书五车。",guide:"数量与才力先被写出，整体评价却仍保留。",note:"为什么知识增多不自动等于完备？"},{text:"天下之辩者相与乐之。",guide:"随后命题属于辩者相应的交流，归属不能一概而论。",note:"列举命题与提供证明之间缺少什么？"},{text:"能胜人之口，不能服人之心。",guide:"取胜未必带来理解与转变。",note:"逻辑成立、对方认可与实际安顿应怎样分别看？"},{text:"多而无已，犹以为寡。",guide:"不断增加论说并未使求知、求胜的活动安定下来。",note:"数量增长何时只是延续原来的失衡？"},{text:"惜乎！惠施之才。",guide:"结尾不是只讥笑无能，还惋惜真实才力的失其归处。",note:"惋惜为何比全盘否定更能解释这里的评价？"},{text:"形与影竞走。",guide:"所用办法延续所欲追尽的问题。",note:"怎样与《渔父》的畏影恶迹对读，而不说两段完全相同？"}];function h(g){return m.filter(t=>t.id.startsWith(`tx-p${g}`))}function p(g){const t=new Set;for(const n of h(g))for(const s of n.sentences)for(const l of s)typeof l!="string"&&l.glossary&&t.add(l.glossary);return x.filter(n=>t.has(n.id)&&Array.from(n.term).length<=5)}const j=h("1"),_=p("1"),S=h("2"),A=p("2"),C=h("3"),V=p("3"),I=h("4"),D=p("4"),R=h("5"),N=p("5");return(g,t)=>{const n=u("DaoReadingPrelude"),s=u("DaoTextReading"),l=u("DaoKeywordCards"),r=u("DaoLineGuide");return K(),v("div",null,[t[0]||(t[0]=i("h1",{id:"庄子·天下",tabindex:"-1"},[e("庄子·天下 "),i("a",{class:"header-anchor",href:"#庄子·天下","aria-label":'Permalink to "庄子·天下"'},"​")],-1)),a(n,{title:"承认一端的价值，也检验一端的限度",summary:"先读道术整体与百家分裂的总纲，再看墨家、宋钘与尹文如何保存救世的一端，以及用意、实践与普遍承担之间的张力。"}),t[1]||(t[1]=d('<p>本篇不只列举学派，也为评议提出一个整体尺度：</p><blockquote><p>各家承接了什么？<br> 实际怎样展开？<br> 有何长处，又遗漏什么？<br> 为什么不能凭一端所得，宣布已经完备？</p></blockquote><p>本批包含两个单元：</p><ol><li><strong>总纲</strong>：古之道术的“备”，与百家学术的“裂”。</li><li><strong>具体评议</strong>：墨家及宋钘、尹文的救世用意与实践限度。</li></ol><p>这里的古之道术带有理想性的整体建构，不直接当成已经得到历史验证的古代学术全貌。</p><h2 id="一、道术整体与百家分裂" tabindex="-1">一、道术整体与百家分裂 <a class="header-anchor" href="#一、道术整体与百家分裂" aria-label="Permalink to &quot;一、道术整体与百家分裂&quot;">​</a></h2>',6)),a(n,{title:"分裂不只是多样，而是一端自足",summary:"从各家自认不可超越，转向根本、精神、教化、制度与民生相通的整体；再辨析百家何以有长处而仍不周遍。"}),t[2]||(t[2]=d('<h3 id="本份范围" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“天下之治方术者多矣，皆以其有为不可加矣！”</li><li><strong>止于</strong>：“道术将为天下裂。”</li><li><strong>连续脉络</strong>：诸家自足 → 道术之问 → 原于一 → 多层实践 → 古人之备 → 传承线索 → 失序 → 一察自好 → 有长不遍 → 往而不反 → 道术之裂。</li></ul><h3 id="原文·连续阅读" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:o(j),glossary:x,"default-mode":"classic","aria-label":"天下·第1份 原文"},null,8,["sections"]),t[3]||(t[3]=i("p",null,[i("strong",null,"文字说明")],-1)),t[4]||(t[4]=i("p",null,"依据所提供文本整理，调整标点与分段。",-1)),t[5]||(t[5]=i("p",null,"开篇问答没有交代具体人物，不补作庄周与某人的对话。",-1)),t[6]||(t[6]=i("p",null,"“宗、精、真”“兆于变化”“本数、末度”“察古人之全”等有训释空间，优先说明整体联系，不强定唯一解释。",-1)),t[7]||(t[7]=i("h3",{id:"关键词卡片",tabindex:"-1"},[e("关键词卡片 "),i("a",{class:"header-anchor",href:"#关键词卡片","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(l,{items:o(_)},null,8,["items"]),t[8]||(t[8]=i("h3",{id:"逐句导读",tabindex:"-1"},[e("逐句导读 "),i("a",{class:"header-anchor",href:"#逐句导读","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:b}),t[9]||(t[9]=i("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:y}),t[10]||(t[10]=d('<h3 id="一、开篇的关键-诸家不只繁多-还各自足" tabindex="-1">一、开篇的关键：诸家不只繁多，还各自足 <a class="header-anchor" href="#一、开篇的关键-诸家不只繁多-还各自足" aria-label="Permalink to &quot;一、开篇的关键：诸家不只繁多，还各自足&quot;">​</a></h3><blockquote><p>天下之治方术者多矣，皆以其有为不可加矣！</p></blockquote><p>“多”说明学说繁盛，问题却落在“不可加”：各家以自己的方法已经足够高明。</p><p>多种研究方向本身不必构成分裂。局部所得被赋予整体完备的地位，才是后文持续检验的问题。</p><p>与《列御寇》“恃其所见入于人”可以对读：两篇都警惕对己之所见的过度倚赖，本篇进一步将它放在天下学术的结构中。</p><h3 id="二、一与无乎不在-共同根本-不是独占招牌" tabindex="-1">二、一与无乎不在：共同根本，不是独占招牌 <a class="header-anchor" href="#二、一与无乎不在-共同根本-不是独占招牌" aria-label="Permalink to &quot;二、一与无乎不在：共同根本，不是独占招牌&quot;">​</a></h3><blockquote><p>古之所谓道术者，果恶乎在？<br> 无乎不在。</p></blockquote><p>道术不能被固定为只在某一家、某制度、某项技能或玄远言说中。</p><p>“皆原于一”与“无乎不在”分别指出：</p><ul><li><strong>根本上的相通</strong>。</li><li><strong>作用与展开的广泛</strong>。</li></ul><p>二者不冲突，但不能推出所有学说都完全正确。后文仍逐家评议所得与失当。</p><p>“神何由降？明何由出？”从所在转问根源，也不必据此将“一”强定为物质元素、人格神或后世概念。</p><h3 id="三、不离宗、精、真-不是明确的升级表" tabindex="-1">三、不离宗、精、真：不是明确的升级表 <a class="header-anchor" href="#三、不离宗、精、真-不是明确的升级表" aria-label="Permalink to &quot;三、不离宗、精、真：不是明确的升级表&quot;">​</a></h3><p>天人、神人、至人的三句共同强调“不离”。</p><p>宗、精、真各有侧重，原文却未完整定义，也未说明名称的排列是逐级晋升。</p><p>**既不强排高低，也不认定三者全然同义。**先把握它们都指向不失根本的联系。</p><h3 id="四、圣人与君子-根本也在变化与人事中展开" tabindex="-1">四、圣人与君子：根本也在变化与人事中展开 <a class="header-anchor" href="#四、圣人与君子-根本也在变化与人事中展开" aria-label="Permalink to &quot;四、圣人与君子：根本也在变化与人事中展开&quot;">​</a></h3><p>圣人以天、德、道为宗本与门径，并“兆于变化”，不是只停在静止境界。</p><p>君子则以仁义礼乐形成关怀、条理、行为与调和：</p><table tabindex="0"><thead><tr><th>所用</th><th>本段所联系的方向</th></tr></thead><tbody><tr><td>仁</td><td>恩惠、关怀</td></tr><tr><td>义</td><td>合宜的条理</td></tr><tr><td>礼</td><td>行为规范与表达</td></tr><tr><td>乐</td><td>和谐、调和</td></tr></tbody></table><p><strong>仁义礼乐被纳入古之道术的整体，而非开篇就被排除。</strong></p><p>后文批评诸家时，需要具体看是运用失当，还是一端独占，不能预设道术就是取消礼乐仁义。</p><h3 id="五、百官与民生-具体规范、衣食养护都有位置" tabindex="-1">五、百官与民生：具体规范、衣食养护都有位置 <a class="header-anchor" href="#五、百官与民生-具体规范、衣食养护都有位置" aria-label="Permalink to &quot;五、百官与民生：具体规范、衣食养护都有位置&quot;">​</a></h3><p>法、名、参、稽分别关联职分、标识、检验与裁决。百官“相齿”说明事务需要条理和衔接。</p><p>“一二三四”不解释为只有四个简单步骤便能治理天下，可先联系有次序的方法理解。</p><p>随后落到衣食、生养、储藏，特别关切老弱孤寡。</p><blockquote><p>老弱孤寡为意，皆有以养。</p></blockquote><p>日常生活与脆弱者的养护是整体的一部分，不是精神境界之外的可有可无之事。</p><p>后文救世评议因此不仅问为何关心天下，更会问是否真正照顾人的生活与承受条件。</p><h3 id="六、古人之备-不是只知本-也不是只守末" tabindex="-1">六、古人之备：不是只知本，也不是只守末 <a class="header-anchor" href="#六、古人之备-不是只知本-也不是只守末" aria-label="Permalink to &quot;六、古人之备：不是只知本，也不是只守末&quot;">​</a></h3><blockquote><p>古之人其备乎！</p></blockquote><p>配神明、醇天地、育万物、和天下、泽百姓构成广大图景。</p><p>“明于本数，系于末度”将根本条理与具体法度联系起来，“小大精粗”再回扣无乎不在。</p><p><strong>备不只是知识多，而是各层面能够相通。</strong></p><p>这是本篇提出的理想，不能直接说历史上某个人已完整实现全部。</p><h3 id="七、典籍与旧法-整体虽隐-传承并非全无" tabindex="-1">七、典籍与旧法：整体虽隐，传承并非全无 <a class="header-anchor" href="#七、典籍与旧法-整体虽隐-传承并非全无" aria-label="Permalink to &quot;七、典籍与旧法：整体虽隐，传承并非全无&quot;">​</a></h3><p>旧法、世传之史与典籍保留了可追寻的方向：</p><table tabindex="0"><thead><tr><th>典籍</th><th>本段概括的表达方向</th></tr></thead><tbody><tr><td>《诗》</td><td>志</td></tr><tr><td>《书》</td><td>事</td></tr><tr><td>《礼》</td><td>行</td></tr><tr><td>《乐》</td><td>和</td></tr><tr><td>《易》</td><td>阴阳</td></tr><tr><td>《春秋》</td><td>名分</td></tr></tbody></table><p>此处“道”作表达、述说义。</p><p>文本承认邹鲁之士、缙绅先生多能明之，但能明一些典籍，不等于已经掌握道术全部。</p><h3 id="八、散布与分裂-多处保存未必失去相通" tabindex="-1">八、散布与分裂：多处保存未必失去相通 <a class="header-anchor" href="#八、散布与分裂-多处保存未必失去相通" aria-label="Permalink to &quot;八、散布与分裂：多处保存未必失去相通&quot;">​</a></h3><table tabindex="0"><thead><tr><th>散布</th><th>分裂</th></tr></thead><tbody><tr><td>不同地方保存、展开</td><td>各端不能相通</td></tr><tr><td>可以有多种传承</td><td>各以一端自足</td></tr><tr><td>不必破坏整体联系</td><td>失去共同根本与整体</td></tr></tbody></table><p>无乎不在并不要求所有内容只存于一处。问题不是多处保存，而是所得一端的人是否仍看见其他层面。</p><h3 id="九、天下失序与一察自好-不只责备个人好胜" tabindex="-1">九、天下失序与一察自好：不只责备个人好胜 <a class="header-anchor" href="#九、天下失序与一察自好-不只责备个人好胜" aria-label="Permalink to &quot;九、天下失序与一察自好：不只责备个人好胜&quot;">​</a></h3><p>“天下大乱，贤圣不明，道德不一”将分裂置于更大传承与社会失序中。</p><p>不一不直接理解为人人必须说同样的话，所失主要是相通与整体。</p><blockquote><p>天下多得一察焉以自好。</p></blockquote><p>可以归纳为：</p><p><strong>得一端 → 自满所得 → 不承认尚有未得 → 以一端充作整体。</strong></p><p>但专门研究不自动等于自好，专注一端与否认一端之外的整体不同。</p><h3 id="十、耳目鼻口-有用与不足同时成立" tabindex="-1">十、耳目鼻口：有用与不足同时成立 <a class="header-anchor" href="#十、耳目鼻口-有用与不足同时成立" aria-label="Permalink to &quot;十、耳目鼻口：有用与不足同时成立&quot;">​</a></h3><p>耳目鼻口各有真实作用，却不能由一个器官承担全部。</p><p>百家也“皆有所长，时有所用”，随后才说“不该不遍”。</p><p><strong>有用不证明完整，不完整不意味着无用。</strong></p><p>比喻没有提出具体协调机构，不补作现代学术组织方案。</p><h3 id="十一、分察与内圣外王-分析后能否返回整体" tabindex="-1">十一、分察与内圣外王：分析后能否返回整体？ <a class="header-anchor" href="#十一、分察与内圣外王-分析后能否返回整体" aria-label="Permalink to &quot;十一、分察与内圣外王：分析后能否返回整体？&quot;">​</a></h3><p>“判”“析”写天地万物被分察，“察古人之全”仍保留疑难说明。</p><p>不必认定所有分析错误。关键是分析之后是否能够回看整体，还是停在割裂部分。</p><p>内圣外王在这里可联系内在根本、圣德与外在治理、养民的相通。</p><p>不独尊一内或一外，也不将后世相关理论全部倒置为本段已经展开的含义。</p><h3 id="十二、往而不反-各立一方-难以相合" tabindex="-1">十二、往而不反：各立一方，难以相合 <a class="header-anchor" href="#十二、往而不反-各立一方-难以相合" aria-label="Permalink to &quot;十二、往而不反：各立一方，难以相合&quot;">​</a></h3><p>“各为其所欲”不是所有个人选择都错，而是自身偏向不再接受更大尺度检验。</p><blockquote><p>百家往而不反，必不合矣！</p></blockquote><p>往是各沿一端展开，反是返回共同根本与整体。</p><p>返回不是机械恢复古代形式。后世“不幸”不见大体，也提示其传承条件受限，不能只归结为缺乏才智。</p><p>后文逐家评议由此不仅责备，也要辨认各家究竟保留了哪一端，又如何在实践中发生偏向。</p><h3 id="本份·核心对照" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>整体的一面</th><th>分裂的一面</th></tr></thead><tbody><tr><td>根本</td><td>皆原于一</td><td>各自立方</td></tr><tr><td>范围</td><td>无乎不在</td><td>一曲之士</td></tr><tr><td>结构</td><td>本数与末度相接</td><td>各端不能相通</td></tr><tr><td>实践</td><td>圣德、治理、民生相联</td><td>一种方法独占评价</td></tr><tr><td>传承</td><td>多处保存仍可相通</td><td>得一察而自好</td></tr><tr><td>能力</td><td>有长处、时有所用</td><td>有用被当成完备</td></tr><tr><td>认识</td><td>分察后返回整体</td><td>往而不反</td></tr><tr><td>后世</td><td>辨认所传的一端</td><td>不见古人之大体</td></tr></tbody></table><h3 id="本份收束" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>两个关键词是 <strong>备</strong> 与 <strong>裂</strong>。</p><p>备是根本、精神、教化、制度与民生相通；裂不是仅有不同学说，而是各得一端便自足，不再返回整体。</p><p>后续持续问：</p><p><strong>承接什么 → 做成什么 → 遗漏什么 → 为什么不能以所长自称完备。</strong></p><h2 id="二、墨家与宋尹·救世的用意与实践限度" tabindex="-1">二、墨家与宋尹·救世的用意与实践限度 <a class="header-anchor" href="#二、墨家与宋尹·救世的用意与实践限度" aria-label="Permalink to &quot;二、墨家与宋尹·救世的用意与实践限度&quot;">​</a></h2>',74)),a(n,{title:"个人坚忍，不自动成为天下的法式",summary:"两组都以救急、止战与安民为方向。评议承认其所得，却继续检验情感生活、普遍承担、劝说分寸与自身养护。"}),t[11]||(t[11]=d('<h3 id="本份范围-1" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-1" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“不侈于后世，不靡于万物……”</li><li><strong>止于</strong>：“其小大精粗，其行适至是而止。”</li><li><strong>两个单元</strong>：墨翟、禽滑厘及后世墨者；宋钘、尹文。</li><li><strong>共同问题</strong>：救世用意怎样成为合乎生活、能够持续承担的实践？</li></ul><h3 id="原文·连续阅读-1" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-1" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:o(S),glossary:x,"default-mode":"classic","aria-label":"天下·第2份 原文"},null,8,["sections"]),t[12]||(t[12]=i("p",null,[i("strong",null,"文字说明")],-1)),t[13]||(t[13]=i("p",null,"依据所提供文本整理，调整标点与分段。",-1)),t[14]||(t[14]=i("p",null,"墨家段“为之大过，已之大顺”“未败墨子道”“乱之上也，治之下也”，宋尹段“别宥”“请欲置之”“图傲”等均有讨论空间，不强行连成唯一译文。",-1)),t[15]||(t[15]=i("p",null,"本篇是在评议诸家，其叙述与评价不直接等于各家完整的自我说明。",-1)),t[16]||(t[16]=i("h3",{id:"关键词卡片-1",tabindex:"-1"},[e("关键词卡片 "),i("a",{class:"header-anchor",href:"#关键词卡片-1","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(l,{items:o(A)},null,8,["items"]),t[17]||(t[17]=i("h3",{id:"逐句导读-1",tabindex:"-1"},[e("逐句导读 "),i("a",{class:"header-anchor",href:"#逐句导读-1","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:c}),t[18]||(t[18]=i("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:q}),t[19]||(t[19]=d('<h3 id="一、先承认道术的一端-再检验实际展开" tabindex="-1">一、先承认道术的一端，再检验实际展开 <a class="header-anchor" href="#一、先承认道术的一端-再检验实际展开" aria-label="Permalink to &quot;一、先承认道术的一端，再检验实际展开&quot;">​</a></h3><p>两组都先说：</p><blockquote><p>古之道术有在于是者。</p></blockquote><p>墨家关联节制、自矫、备急；宋尹关联不受俗累、不伤众人、安民足养。</p><table tabindex="0"><thead><tr><th>所承方向</th><th>实际展开后要检验</th></tr></thead><tbody><tr><td>节制物用</td><td>是否过度苛苦？</td></tr><tr><td>爱人救急</td><td>是否压缩情感与生活？</td></tr><tr><td>安民止战</td><td>是否不顾情境而强说？</td></tr><tr><td>人我足养</td><td>是否仍使自身匮乏？</td></tr></tbody></table><p>不是从开头全盘否定，而是承认方向后仍审察方式与限度。</p><h3 id="二、墨家节用-何时成为严苛的普遍规范" tabindex="-1">二、墨家节用：何时成为严苛的普遍规范？ <a class="header-anchor" href="#二、墨家节用-何时成为严苛的普遍规范" aria-label="Permalink to &quot;二、墨家节用：何时成为严苛的普遍规范？&quot;">​</a></h3><p>生不歌、死无服、桐棺无椁被置于古代礼乐对照中。</p><p>重点不只在古已有礼所以必须照办，而在节省是否被推成对生活表达的全面压缩。</p><blockquote><p>以此教人，恐不爱人；以此自行，固不爱己。</p></blockquote><p>爱人的用意与不顾承受的教法可能冲突，自矫也可能过度。</p><p>不将批评扩大为一切节俭都是不爱人。<strong>关键在过度及立为人人应行的法式。</strong></p><h3 id="三、歌哭与乐-节用是否仍兼顾情感" tabindex="-1">三、歌哭与乐：节用是否仍兼顾情感？ <a class="header-anchor" href="#三、歌哭与乐-节用是否仍兼顾情感" aria-label="Permalink to &quot;三、歌哭与乐：节用是否仍兼顾情感？&quot;">​</a></h3><blockquote><p>歌而非歌，哭而非哭，乐而非乐，是果类乎？</p></blockquote><p>“非”联系否定、非议，将情感活动及对它们的压抑并置。</p><p>这不证明任何音乐或丧礼都不得限制，而是问：物用节省与情感生活能否协调？</p><p>第一份已将礼乐纳入整体，只保存节用一端，可能损伤其他需要。</p><h3 id="四、个人能任-不证明天下能任" tabindex="-1">四、个人能任，不证明天下能任 <a class="header-anchor" href="#四、个人能任-不证明天下能任" aria-label="Permalink to &quot;四、个人能任，不证明天下能任&quot;">​</a></h3><blockquote><p>天下不堪。墨子虽独能任，奈天下何！</p></blockquote><p>个人坚忍与普遍可行不同。倡导者真诚，不免除对不同人的承受条件的检验。</p><p>“去王也远”可联系治理天下：严苦自持未必就能形成适合众人的制度与生活安排。</p><p><strong>救世不是要求天下人人成为倡导者本人。</strong></p><h3 id="五、法禹-劳苦从解决问题的代价转成资格" tabindex="-1">五、法禹：劳苦从解决问题的代价转成资格 <a class="header-anchor" href="#五、法禹-劳苦从解决问题的代价转成资格" aria-label="Permalink to &quot;五、法禹：劳苦从解决问题的代价转成资格&quot;">​</a></h3><p>禹疏水、执器、冒风雨、劳损形体，劳苦原与解除灾难相连。</p><p>后学却被描写为：</p><blockquote><p>日夜不休，以自苦为极。</p></blockquote><p>并以不能如此便不足称墨作为准入判断。</p><p><strong>因救灾而劳苦 → 效法劳苦形象 → 自苦成为极则 → 以受苦程度判断身份。</strong></p><p>问题不是禹的劳动无价值，而是完成事情的代价被抽离为独立的德行指标。</p><h3 id="六、后学分歧-共同经典不自动形成相通" tabindex="-1">六、后学分歧：共同经典不自动形成相通 <a class="header-anchor" href="#六、后学分歧-共同经典不自动形成相通" aria-label="Permalink to &quot;六、后学分歧：共同经典不自动形成相通&quot;">​</a></h3><p>“俱诵《墨经》”与“相谓别墨”并置，共享经典却相互排斥、争辩和争夺传承。</p><p>这落实总纲：共同来源不保证整体相通，正统认同也可能加重一端自足。</p><p>但本篇选择呈现分裂问题，不是后学完整历史，不能说全部墨家活动只剩争辩。</p><h3 id="七、意、行、人物-敬重不取消批评" tabindex="-1">七、意、行、人物：敬重不取消批评 <a class="header-anchor" href="#七、意、行、人物-敬重不取消批评" aria-label="Permalink to &quot;七、意、行、人物：敬重不取消批评&quot;">​</a></h3><blockquote><p>墨翟、禽滑厘之意则是，其行则非也。</p></blockquote><table tabindex="0"><thead><tr><th>层次</th><th>本段评价方向</th></tr></thead><tbody><tr><td>用意</td><td>承认爱天下、救急与节制</td></tr><tr><td>实践</td><td>批评过度自苦与普遍推广</td></tr><tr><td>人物</td><td>肯定坚忍、才力与枯槁不舍</td></tr></tbody></table><p>“乱之上也，治之下也”等疑难不强译，前后主要区分仍可把握。</p><p>本篇可以敬重墨子，又认为其所行不能充作完整之道。这是有长而不遍的具体展开。</p><h3 id="八、宋尹起点-养人-也养己" tabindex="-1">八、宋尹起点：养人，也养己 <a class="header-anchor" href="#八、宋尹起点-养人-也养己" aria-label="Permalink to &quot;八、宋尹起点：养人，也养己&quot;">​</a></h3><blockquote><p>愿天下之安宁以活民命，人我之养，毕足而止。</p></blockquote><p>基本方向是活命、足养、不过求，不是先将自苦立为最高准则。</p><p>后文为人太多、自为太少，因此不是无关生活小事，而是所行没有充分实现原先的人我足养。</p><p>别宥、心之行与聏等处保留字义讨论，不凭现有材料扩写成完整心性体系。</p><h3 id="九、见侮不辱-止争不等于否认损害" tabindex="-1">九、见侮不辱：止争不等于否认损害 <a class="header-anchor" href="#九、见侮不辱-止争不等于否认损害" aria-label="Permalink to &quot;九、见侮不辱：止争不等于否认损害&quot;">​</a></h3><p>个人受侮、民间争斗与攻伐战争连成由小到大的止争方向。</p><p>可联系：不将受侮直接认成必须通过报复洗雪的羞辱，以阻断冲突扩大。</p><p><strong>不能据此要求受害者沉默，或否认实际伤害。</strong></p><p>原文没有给出所有伤害情境的处理规则。</p><h3 id="十、强聒不舍-坚持还需应人" tabindex="-1">十、强聒不舍：坚持还需应人 <a class="header-anchor" href="#十、强聒不舍-坚持还需应人" aria-label="Permalink to &quot;十、强聒不舍：坚持还需应人&quot;">​</a></h3><p>周行天下、上说下教，显示热切；天下不取仍反复强说，又显示接受情境与方法之间的张力。</p><p>两面都应保留：</p><ul><li>不轻易放弃救世。</li><li>不被接受时仍不改方式。</li></ul><p>不能只赞美坚持，也不能只据强说抹去用意。须问是否因人、因时、因处境调整。</p><h3 id="十一、为人太多-持续行动的条件是否被损耗" tabindex="-1">十一、为人太多：持续行动的条件是否被损耗？ <a class="header-anchor" href="#十一、为人太多-持续行动的条件是否被损耗" aria-label="Permalink to &quot;十一、为人太多：持续行动的条件是否被损耗？&quot;">​</a></h3><p>饭食不足、先生弟子饥而不休，落实自养失衡。</p><p>“五升之饭”不未经度量与语境考察换算成现代食量，“图傲”等也不强定。</p><p>可辨明的是：欲求压低，自身养护仍显紧迫，救世活动却持续不止。</p><p><strong>批评不是不应关怀，而是关怀能否保留持续行动的条件。</strong></p><h3 id="十二、不以身假物-主张是否也兑现于自身" tabindex="-1">十二、不以身假物：主张是否也兑现于自身？ <a class="header-anchor" href="#十二、不以身假物-主张是否也兑现于自身" aria-label="Permalink to &quot;十二、不以身假物：主张是否也兑现于自身？&quot;">​</a></h3><p>宋尹倡导不苛察、不使自身受物役，但前文奔忙、强说、自养不足，使读者继续问：</p><p>救世目标是否反而成为不能松开的驱使？</p><p>这不是证明关怀虚假，而是检查不受物役是否实际落实。</p><p>“明之不如己”也可联系总纲自好：以有益天下作为尺度，是否又把自己的救世方向当成优越凭据？具体语法与范围仍须保留。</p><h3 id="十三、止战与寡欲-有内外方向-仍不等于全部" tabindex="-1">十三、止战与寡欲：有内外方向，仍不等于全部 <a class="header-anchor" href="#十三、止战与寡欲-有内外方向-仍不等于全部" aria-label="Permalink to &quot;十三、止战与寡欲：有内外方向，仍不等于全部&quot;">​</a></h3><blockquote><p>以禁攻寝兵为外，以情欲寡浅为内。<br> 其小大精粗，其行适至是而止。</p></blockquote><p>这明确概括所得，也明确划定范围。</p><p>不因有限便说止战寡欲无价值，也不因有内外安排便认定完整实现内圣外王。</p><h3 id="十四、两组合读-救世热切须接受生活与整体检验" tabindex="-1">十四、两组合读：救世热切须接受生活与整体检验 <a class="header-anchor" href="#十四、两组合读-救世热切须接受生活与整体检验" aria-label="Permalink to &quot;十四、两组合读：救世热切须接受生活与整体检验&quot;">​</a></h3><table tabindex="0"><thead><tr><th>墨家</th><th>宋钘、尹文</th></tr></thead><tbody><tr><td>节用与薄葬</td><td>止战与寡欲</td></tr><tr><td>法禹并推重自苦</td><td>周行天下、反复劝说</td></tr><tr><td>个人能任，天下未必能任</td><td>为人太多，自养不足</td></tr><tr><td>后学以苦相进、传承分歧</td><td>所行止于特定内外范围</td></tr><tr><td>明确分判意与行</td><td>揭示方向与实践失衡</td></tr></tbody></table><p>共同提醒：</p><p><strong>自己的坚忍不自动成为众人的义务，自己的热切不自动证明方法适用于所有处境。</strong></p><h3 id="本份·核心对照-1" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-1" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>道术方向</td><td>古之道术有在于是者</td><td>承认真实所得</td><td>开头即全盘否定</td></tr><tr><td>墨家法式</td><td>桐棺三寸而无椁</td><td>节制与普遍规范</td><td>所有节俭不爱人</td></tr><tr><td>情感</td><td>歌而非歌，哭而非哭</td><td>生活表达与节用协调</td><td>礼乐全不能限制</td></tr><tr><td>承担</td><td>墨子虽独能任</td><td>个人与天下承受不同</td><td>真诚保证普遍合宜</td></tr><tr><td>自苦</td><td>以自苦为极</td><td>代价转成资格</td><td>救灾劳苦无价值</td></tr><tr><td>后学</td><td>相谓别墨</td><td>经典共享未必相通</td><td>全部墨者只会争辩</td></tr><tr><td>总评</td><td>意则是，其行则非</td><td>用意、实践、人物分看</td><td>全对或全错</td></tr><tr><td>宋尹起点</td><td>人我之养，毕足而止</td><td>养人也养己</td><td>本来就主张牺牲自己</td></tr><tr><td>止争</td><td>见侮不辱</td><td>阻断报复扩大</td><td>否认受害损失</td></tr><tr><td>劝说</td><td>强聒而不舍</td><td>坚持与分寸</td><td>坚持全无价值</td></tr><tr><td>自养</td><td>为人太多，自为太少</td><td>保留持续行动条件</td><td>不应帮助他人</td></tr><tr><td>限度</td><td>适至是而止</td><td>有所得仍有限</td><td>止战寡欲全无意义</td></tr></tbody></table><h3 id="本份收束-1" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-1" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>文本承认墨子的用意与坚忍，也承认宋尹的安民止战，却不因此停止检验：</p><ul><li>节用是否兼顾情感与生活？</li><li>自苦能否作为所有人的法式？</li><li>救世是否仍保留自身养护？</li><li>明确方向能否代表完整道术？</li></ul><p>总纲在此落实为：</p><p><strong>所长值得承认，所行仍须检验，所守不能自称全部。</strong></p><p>下一批继续彭蒙、田骈、慎到及关尹、老聃等评议，再统一完成全篇收束。</p><h2 id="三、彭田慎与关老·随物与应物·无己的实践边界" tabindex="-1">三、彭田慎与关老·随物与应物·无己的实践边界 <a class="header-anchor" href="#三、彭田慎与关老·随物与应物·无己的实践边界" aria-label="Permalink to &quot;三、彭田慎与关老·随物与应物·无己的实践边界&quot;">​</a></h2>',80)),a(n,{title:"不立己，是否就等于无知随转？",summary:"两组都不以争先与私己为中心，却受到明显不同的评价。合读去己、无居与不毁物，辨析不强作如何仍是活人的实践。"}),t[20]||(t[20]=d('<h3 id="本份范围-2" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-2" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“公而不党，易而无私……”</li><li><strong>止于</strong>：“古之博大真人哉！”</li><li><strong>两个单元</strong>：彭蒙、田骈、慎到；关尹、老聃。</li><li><strong>连续脉络</strong>：无私齐物 → 去己随转 → 无知之物 → 批评并承认有所闻 → 重本取虚 → 无居应物 → 柔下宽容 → 博大而未极。</li></ul><h3 id="原文·连续阅读-2" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-2" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:o(C),glossary:x,"default-mode":"classic","aria-label":"天下·第3份 原文"},null,8,["sections"]),t[21]||(t[21]=i("p",null,[i("strong",null,"文字说明")],-1)),t[22]||(t[22]=i("p",null,"本份原文取自此次提供的全篇文本，解读为补写稿，未作版本对勘。",-1)),t[23]||(t[23]=i("p",null,"“趣物而不两”“泠汰”“謑髁”“椎拍輐断”“魏然”“窨然”“魭断”“常无有”等处保留训释空间。",-1)),t[24]||(t[24]=i("p",null,"慎到段的豪杰讥评、各人物所言与篇末叙述评价分开，不将《天下》的选择性评议等同于各人的完整历史学说。",-1)),t[25]||(t[25]=i("h3",{id:"关键词卡片-2",tabindex:"-1"},[e("关键词卡片 "),i("a",{class:"header-anchor",href:"#关键词卡片-2","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(l,{items:o(V)},null,8,["items"]),t[26]||(t[26]=i("h3",{id:"逐句导读-2",tabindex:"-1"},[e("逐句导读 "),i("a",{class:"header-anchor",href:"#逐句导读-2","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:k}),t[27]||(t[27]=i("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:f}),t[28]||(t[28]=d('<h3 id="一、两组共同起点-不以私己偏取为中心" tabindex="-1">一、两组共同起点：不以私己偏取为中心 <a class="header-anchor" href="#一、两组共同起点-不以私己偏取为中心" aria-label="Permalink to &quot;一、两组共同起点：不以私己偏取为中心&quot;">​</a></h3><p>彭田慎之前先写公而不党、无私、无择、与物俱往，仍承认古之道术有在于是。</p><p>天能覆而不能载、地能载而不能覆，说明某种真实能力也有不能。</p><p>“选则不遍”进一步警惕以局部取舍代表全部。</p><p><strong>这是真实所得，不意味着后文所有实践都获得认可。</strong></p><p>不以己私排物，与取消一切选择、教育和判断不是同一件事。</p><h3 id="二、慎到-从去己到无知之物" tabindex="-1">二、慎到：从去己到无知之物 <a class="header-anchor" href="#二、慎到-从去己到无知之物" aria-label="Permalink to &quot;二、慎到：从去己到无知之物&quot;">​</a></h3><p>弃知去己、缘不得已，本可联系不强作、不以成见主宰。</p><p>随后却被描写为舍是非只求免、不师知虑、推而后行、曳而后往，并以风、羽、磨石比拟。</p><p><strong>本段检验的是：消除自我患累的要求，是否被推成消除活人的辨别、承担与应对。</strong></p><p>无知之物没有建己用知之累，也不会因其自身意图而获罪；但免于这些问题，尚不足以成为活人的完整实践。</p><p>豪杰说“非生人之行”，应先作为所引批评理解，不能直接扩成慎到全部思想的定义。</p><h3 id="三、彭田慎总评-严厉批评-仍有所得" tabindex="-1">三、彭田慎总评：严厉批评，仍有所得 <a class="header-anchor" href="#三、彭田慎总评-严厉批评-仍有所得" aria-label="Permalink to &quot;三、彭田慎总评：严厉批评，仍有所得&quot;">​</a></h3><p>彭蒙田骈继续被置于不教、莫是莫非与随转的方向中，疑难句不强译。</p><p>最后说三人不知道，又说：</p><blockquote><p>虽然，概乎皆尝有闻者也。</p></blockquote><p>转折保留听闻道术一端的价值。</p><p>不能只留严厉结论，删去其所得；也不能仅因有所闻，就抹去生人实践的限度。</p><h3 id="四、关老-重本不等于轻毁万物" tabindex="-1">四、关老：重本不等于轻毁万物 <a class="header-anchor" href="#四、关老-重本不等于轻毁万物" aria-label="Permalink to &quot;四、关老：重本不等于轻毁万物&quot;">​</a></h3><p>关老以本为精、以物为粗，不以积聚为足，主于太一。</p><p>随后立即区分：</p><table tabindex="0"><thead><tr><th>表</th><th>实</th></tr></thead><tbody><tr><td>濡弱谦下</td><td>空虚不毁万物</td></tr></tbody></table><p>不只是外在柔弱，更有不毁物的实际内容。</p><p><strong>根本上的空虚需要在关系中兑现，不应成为损物、削人的借口。</strong></p><h3 id="五、关尹无居-不固着-却能相应" tabindex="-1">五、关尹无居：不固着，却能相应 <a class="header-anchor" href="#五、关尹无居-不固着-却能相应" aria-label="Permalink to &quot;五、关尹无居：不固着，却能相应&quot;">​</a></h3><p>水、镜、响分别表现流动、照见与回应。</p><p>“在己无居”可联系不先固守一个私己位置，让事物显现。</p><p>与慎到段相比，关尹不是仅以推曳才行、免患为终点，而被描写为与物相应。</p><p>这是篇内评价的对照，不宣称已经完成两家全部哲学的系统比较。</p><h3 id="六、老聃处后-柔下与不自耗" tabindex="-1">六、老聃处后：柔下与不自耗 <a class="header-anchor" href="#六、老聃处后-柔下与不自耗" aria-label="Permalink to &quot;六、老聃处后：柔下与不自耗&quot;">​</a></h3><p>知雄守雌、取后取虚，不让争先、占有、尖锐自显成为中心。</p><p>“徐而不费”“以深为根，以约为纪”将行动的舒缓、节制与根本联系。</p><p>不宜把守辱解释为认可侵害，也不将无藏有余当成现实无需储备的保证。</p><p><strong>无为并不是一句不做事，而是不以强作机巧耗己伤物。</strong></p><h3 id="七、宽容不削-评价的实质落在人我关系" tabindex="-1">七、宽容不削：评价的实质落在人我关系 <a class="header-anchor" href="#七、宽容不削-评价的实质落在人我关系" aria-label="Permalink to &quot;七、宽容不削：评价的实质落在人我关系&quot;">​</a></h3><p>坚毁、锐挫提醒强显可能形成损折，段末落实为宽容万物、不削于人。</p><p>所肯定的不只避免自身祸患，也是不以己意侵削别人。</p><p>最后高度赞为博大真人，却明确说“未至于极”。</p><p>赞许与未极同时成立，不能删掉任何一面。</p><h3 id="八、两组为什么受到不同评价" tabindex="-1">八、两组为什么受到不同评价？ <a class="header-anchor" href="#八、两组为什么受到不同评价" aria-label="Permalink to &quot;八、两组为什么受到不同评价？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>比较方向</th><th>彭蒙、田骈、慎到</th><th>关尹、老聃</th></tr></thead><tbody><tr><td>共同所得</td><td>不偏取、不强立己</td><td>取虚、柔下、不争先</td></tr><tr><td>主要描写</td><td>去知随转、只求免患</td><td>无居相应、不毁万物</td></tr><tr><td>所受检验</td><td>是否仍是生人之行？</td><td>是否实际宽容不削？</td></tr><tr><td>总评</td><td>不知道，但曾有闻</td><td>博大真人，但未极</td></tr></tbody></table><p>不应简单概括为一组什么也不做、另一组善于做事。</p><p>更稳妥的联系是：</p><p><strong>去己不能取消活的应物，重本不能取消对万物与他人的实际照顾。</strong></p><h3 id="本份·核心对照-2" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-2" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>无私</td><td>公而不党</td><td>承认道术方向</td><td>全部实践已合宜</td></tr><tr><td>无遗</td><td>选则不遍</td><td>局部取舍的限度</td><td>取消所有选择</td></tr><tr><td>去己</td><td>弃知去己</td><td>不强执私己</td><td>活人应无知</td></tr><tr><td>随转</td><td>推而后行</td><td>机械随转的风险</td><td>不强作就只能被动</td></tr><tr><td>总评</td><td>皆尝有闻</td><td>批评仍保留所得</td><td>全无价值</td></tr><tr><td>表实</td><td>空虚不毁万物</td><td>柔下须有实质</td><td>姿态独自证明德</td></tr><tr><td>应物</td><td>应若响</td><td>无居与相应</td><td>等同无知土块</td></tr><tr><td>宽容</td><td>不削于人</td><td>通本落实于关系</td><td>只为自己免祸</td></tr><tr><td>界限</td><td>虽未至于极</td><td>赞许仍有尺度</td><td>全盘否定或最终完备</td></tr></tbody></table><h3 id="本份收束-2" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-2" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>不立己、不强作确有价值，但不能仅靠取消判断来免患。</p><p>关老的积极评价落在无居应物、空虚不毁、宽容不削；即便如此，仍未被确认为极致。</p><p>总纲的尺度继续有效：<strong>有所得，也要问它怎样成为活人的实践。</strong></p><h2 id="四、庄周·三言与应化·精神广大而不傲物" tabindex="-1">四、庄周·三言与应化·精神广大而不傲物 <a class="header-anchor" href="#四、庄周·三言与应化·精神广大而不傲物" aria-label="Permalink to &quot;四、庄周·三言与应化·精神广大而不傲物&quot;">​</a></h2>',51)),a(n,{title:"不把变化锁进固定说法",summary:"由无形与连续发问进入三言，合读文辞自由、天地精神、不傲万物及应化解物，保留未之尽的解释边界。"}),t[29]||(t[29]=d('<h3 id="本份范围-3" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-3" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“寂漠无形，变化无常……”</li><li><strong>止于</strong>：“芒乎昧乎，未之尽者。”</li><li><strong>连续脉络</strong>：变化之问 → 庄周所承 → 广远言说 → 三言 → 不傲物 → 书辞充实 → 通本宗 → 应化未尽。</li></ul><h3 id="原文·连续阅读-3" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-3" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:o(I),glossary:x,"default-mode":"classic","aria-label":"天下·第4份 原文"},null,8,["sections"]),t[30]||(t[30]=i("p",null,[i("strong",null,"文字说明")],-1)),t[31]||(t[31]=i("p",null,"依据所提供文本整理。“不傥，不奇见之也”“连犿”“稠适而上遂”“其来不蜕”等保留讨论空间。",-1)),t[32]||(t[32]=i("p",null,"本篇以第三人称评议庄周，不据此认定为无疑的本人自述。",-1)),t[33]||(t[33]=i("p",null,"“未之尽者”可能涉及评议未尽、应化之理难尽或未究竟的保留，不未经辨析便定为简单不足判语。",-1)),t[34]||(t[34]=i("h3",{id:"关键词卡片-3",tabindex:"-1"},[e("关键词卡片 "),i("a",{class:"header-anchor",href:"#关键词卡片-3","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(l,{items:o(D)},null,8,["items"]),t[35]||(t[35]=i("h3",{id:"逐句导读-3",tabindex:"-1"},[e("逐句导读 "),i("a",{class:"header-anchor",href:"#逐句导读-3","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:z}),t[36]||(t[36]=i("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:P}),t[37]||(t[37]=d('<h3 id="一、先写道术方向-无形不等于无理" tabindex="-1">一、先写道术方向：无形不等于无理 <a class="header-anchor" href="#一、先写道术方向-无形不等于无理" aria-label="Permalink to &quot;一、先写道术方向：无形不等于无理&quot;">​</a></h3><p>开篇仍先描绘所承方向，再写庄周闻风。</p><p>无形、无常强调不被固定样式拘住，不意味着万物毫无条理。</p><p>后文“其理不竭”恰保留可通达的理。</p><h3 id="二、连续发问-不匆忙固定死生与天地" tabindex="-1">二、连续发问：不匆忙固定死生与天地 <a class="header-anchor" href="#二、连续发问-不匆忙固定死生与天地" aria-label="Permalink to &quot;二、连续发问：不匆忙固定死生与天地&quot;">​</a></h3><p>死生、天地、神明、去向都以问句展开，不立即给出封闭答案。</p><p>不把它们改写为已证明的死生同一、个人永存或宇宙最终目的。</p><p>“万物毕罗，莫足以归”可联系不以某一物独占最终归着，却不否定万物价值。</p><p>后文不傲物、与世俗处，说明不执一物并非拒绝关系。</p><h3 id="三、广远言说-摆脱现代贬义-也不凭奇异自证" tabindex="-1">三、广远言说：摆脱现代贬义，也不凭奇异自证 <a class="header-anchor" href="#三、广远言说-摆脱现代贬义-也不凭奇异自证" aria-label="Permalink to &quot;三、广远言说：摆脱现代贬义，也不凭奇异自证&quot;">​</a></h3><p>谬悠、荒唐、无端崖宜联系悠远、广大、不拘边际。</p><p>不能直接译成错误百出，也不能反向说漫无边际必然深刻。</p><p>“不傥、不奇见”常读为不偏执、不自炫，仍保留疑难。</p><p><strong>言说自由需要同时看实质、无伤与根本联系。</strong></p><h3 id="四、天下沈浊-改变如何被听见" tabindex="-1">四、天下沈浊：改变如何被听见 <a class="header-anchor" href="#四、天下沈浊-改变如何被听见" aria-label="Permalink to &quot;四、天下沈浊：改变如何被听见&quot;">​</a></h3><p>“庄语”是正面庄重的言说，不是庄周之语。</p><p>正面宣讲可能受既有口号、归类与是非格局限制，于是需要不同表达方式。</p><p>不因此判天下人都无理解能力，也不让言说者免于责任。</p><h3 id="五、三言-改变观看与表达的位置" tabindex="-1">五、三言：改变观看与表达的位置 <a class="header-anchor" href="#五、三言-改变观看与表达的位置" aria-label="Permalink to &quot;五、三言：改变观看与表达的位置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>本段作用</th><th>不宜误读</th></tr></thead><tbody><tr><td>卮言</td><td>曼衍，随化伸展</td><td>任意摇摆、不必解释</td></tr><tr><td>重言</td><td>真，借重增信</td><td>权威保证正确</td></tr><tr><td>寓言</td><td>广，寄言他者</td><td>每个故事只有固定寓意</td></tr></tbody></table><p>三言不是只使文字好看，而是让读者从人物、行动、不同位置理解问题。</p><p>不应将所有故事压成作者一句正面断言的装饰。</p><h3 id="六、独与天地往来-仍不傲倪万物" tabindex="-1">六、独与天地往来，仍不傲倪万物 <a class="header-anchor" href="#六、独与天地往来-仍不傲倪万物" aria-label="Permalink to &quot;六、独与天地往来，仍不傲倪万物&quot;">​</a></h3><p>“独”与“不敖倪”必须连读：精神独特不成为轻慢别人和万物的资格。</p><p>不谴是非可联系不靠固定责斥确立优越，不能解释为关怀与伤害毫无差别。</p><p>本篇正在作评价，因而应区分辨明问题与以谴责立己。</p><p>与世俗相处也不自动等于迎合世俗。</p><h3 id="七、书辞奇异-仍以无伤、可观与充实衡量" tabindex="-1">七、书辞奇异，仍以无伤、可观与充实衡量 <a class="header-anchor" href="#七、书辞奇异-仍以无伤、可观与充实衡量" aria-label="Permalink to &quot;七、书辞奇异，仍以无伤、可观与充实衡量&quot;">​</a></h3><p>两个“虽”不排除奇异形式，却把肯定落在宛转无伤、諔诡可观与内容充实。</p><p>无伤不保证读者永不受冲击，也不取消讽刺锋芒。</p><p>“不可以已”不凭字数自证完备，仍须看表达与精神内容如何相接。</p><h3 id="八、造化与本宗-不是只赞文学技巧" tabindex="-1">八、造化与本宗：不是只赞文学技巧 <a class="header-anchor" href="#八、造化与本宗-不是只赞文学技巧" aria-label="Permalink to &quot;八、造化与本宗：不是只赞文学技巧&quot;">​</a></h3><p>与造物者游、友于外死生无终始者，强调不以固定死生终始为最终拘束。</p><p>不证明个人永生，不否认身体死亡与现实哀伤。</p><p>弘大、深闳与稠适上遂将评价推进到根本通达，不仅是文学才能。</p><h3 id="九、虽然与未尽-不封成最终定案" tabindex="-1">九、虽然与未尽：不封成最终定案 <a class="header-anchor" href="#九、虽然与未尽-不封成最终定案" aria-label="Permalink to &quot;九、虽然与未尽：不封成最终定案&quot;">​</a></h3><p>应化解物回到开头的变化与万物，通本并非只停在抽象境界。</p><p>“其来不蜕”不强译，“未之尽”保留几种读法：</p><ul><li>评议尚未穷尽。</li><li>应化之理难以穷尽。</li><li>通达仍有未究竟的保留。</li></ul><p>高度赞许是明确的，最终封闭定案则不是。</p><p><strong>未之尽不直接等同于关老未至于极。</strong></p><h3 id="十、对总纲的回应-不仅提出另一端口号" tabindex="-1">十、对总纲的回应：不仅提出另一端口号 <a class="header-anchor" href="#十、对总纲的回应-不仅提出另一端口号" aria-label="Permalink to &quot;十、对总纲的回应：不仅提出另一端口号&quot;">​</a></h3><p>不固定形态，不固守单一表达位置，不傲物，不靠责斥立己，并通本应化。</p><p>这些可理解为回应一察自好的方式，试图避免言说再次成为一曲。</p><p>但不据此宣布庄周每句文字都已完成所有问题。</p><h3 id="本份·核心对照-3" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-3" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>方向</td><td>变化无常</td><td>不固守样式</td><td>毫无条理</td></tr><tr><td>问句</td><td>死与？生与？</td><td>松开定论</td><td>已证明永生</td></tr><tr><td>归着</td><td>莫足以归</td><td>不以一物为终点</td><td>万物无价值</td></tr><tr><td>言说</td><td>谬悠、荒唐</td><td>广远不拘常格</td><td>错误或奇异必深刻</td></tr><tr><td>三言</td><td>卮言、重言、寓言</td><td>多重表达位置</td><td>任意、权威、单一寓意</td></tr><tr><td>关系</td><td>不敖倪于万物</td><td>广大而不轻慢</td><td>超越便能傲物</td></tr><tr><td>世俗</td><td>不谴是非</td><td>不靠责斥立己</td><td>取消判断责任</td></tr><tr><td>书辞</td><td>无伤、可观、充实</td><td>自由仍有实质</td><td>奇异足够</td></tr><tr><td>造化</td><td>外死生</td><td>不执死生终始</td><td>死亡不存在</td></tr><tr><td>本宗</td><td>弘大而辟</td><td>根本通达</td><td>仅文学赞美</td></tr><tr><td>收束</td><td>未之尽者</td><td>难尽与未尽</td><td>简单不足或最终完整</td></tr></tbody></table><h3 id="本份收束-3" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-3" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>庄周评议将四条线索相接：</p><p><strong>不固形 → 三言展开 → 精神广大而不傲物 → 通本并应化解物。</strong></p><p>特殊之处不只在奇异文辞，而在言说自由与应物不固着相联。</p><p>不把活的变化锁进一个说法，也不以精神超越换取对具体万物的轻慢。</p><h2 id="五、惠施与辩者·命题与胜负·逐物而不反" tabindex="-1">五、惠施与辩者·命题与胜负·逐物而不反 <a class="header-anchor" href="#五、惠施与辩者·命题与胜负·逐物而不反" aria-label="Permalink to &quot;五、惠施与辩者·命题与胜负·逐物而不反&quot;">​</a></h2>',53)),a(n,{title:"论说越来越多，为什么仍不能自宁？",summary:"依据全篇原文补写。区分惠施所列见解与辩者相应命题，检验才学、争胜、服心和自身安顿，并回扣往而不反的总纲。"}),t[38]||(t[38]=d('<h3 id="本份范围-4" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-4" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“惠施多方，其书五车……”</li><li><strong>止于</strong>：“形与影竞走也，悲夫！”</li><li><strong>连续脉络</strong>：才学总评 → 历物命题 → 辩者相应 → 胜口不服心 → 自贤求胜 → 强物弱德 → 不能自宁 → 逐物不反。</li></ul><h3 id="原文·连续阅读-4" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-4" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:o(R),glossary:x,"default-mode":"classic","aria-label":"天下·第5份 原文"},null,8,["sections"]),t[39]||(t[39]=i("p",null,[i("strong",null,"文字说明")],-1)),t[40]||(t[40]=i("p",null,"本份依据此次提供的全篇原文补写，未作逐字版本校勘。",-1)),t[41]||(t[41]=i("p",null,"多数命题只被列出，没有附论证。以下按问题方向分类，不将某种现代重构当成唯一原义。",-1)),t[42]||(t[42]=i("p",null,"惠施“历物之意”与随后天下辩者的命题分开；不能将全部命题无差别归于惠施个人。",-1)),t[43]||(t[43]=i("p",null,"“施存雄而无术”“其涂隩矣”“夫充一尚可……”等保留字义与句法空间。",-1)),t[44]||(t[44]=i("h3",{id:"关键词卡片-4",tabindex:"-1"},[e("关键词卡片 "),i("a",{class:"header-anchor",href:"#关键词卡片-4","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(l,{items:o(N)},null,8,["items"]),t[45]||(t[45]=i("h3",{id:"逐句导读-4",tabindex:"-1"},[e("逐句导读 "),i("a",{class:"header-anchor",href:"#逐句导读-4","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(r,{lines:T}),t[46]||(t[46]=i("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{lines:w}),t[47]||(t[47]=d('<h3 id="一、多方五车-才学丰厚仍不等于完备" tabindex="-1">一、多方五车：才学丰厚仍不等于完备 <a class="header-anchor" href="#一、多方五车-才学丰厚仍不等于完备" aria-label="Permalink to &quot;一、多方五车：才学丰厚仍不等于完备&quot;">​</a></h3><p>开篇承认知识范围与数量，同时作舛驳、不中的批评。</p><p>不能据此说惠施毫无能力，也不能凭书多证明整体已通。</p><p>“不中”是篇内评价，不省略论证便认定每条命题都形式错误。</p><h3 id="二、历物命题-挑战通常尺度与分类" tabindex="-1">二、历物命题：挑战通常尺度与分类 <a class="header-anchor" href="#二、历物命题-挑战通常尺度与分类" aria-label="Permalink to &quot;二、历物命题：挑战通常尺度与分类&quot;">​</a></h3><p>可以按阅读问题归类：</p><table tabindex="0"><thead><tr><th>方向</th><th>原文例子</th><th>阅读时须注意</th></tr></thead><tbody><tr><td>大小、内外</td><td>大一、小一</td><td>定义尺度，不直接等同道术之“一”</td></tr><tr><td>厚度、范围</td><td>无厚而大千里</td><td>不强定现代数学对象</td></tr><tr><td>高低与变化</td><td>天地卑、山泽平、日中方睨</td><td>原文未附详细论证</td></tr><tr><td>同异层次</td><td>小同异、大同异</td><td>比较标准可能变化</td></tr><tr><td>时空与位置</td><td>今日适越、天之中央</td><td>不当实际地理或年代记录</td></tr><tr><td>整体关怀</td><td>泛爱万物、天地一体</td><td>说一体不自证整体实践</td></tr></tbody></table><p>反常表达可以使惯常判断受检验，但反常本身既不证明错误，也不证明深刻。</p><h3 id="三、辩者命题-共同响应-不强合为一套系统" tabindex="-1">三、辩者命题：共同响应，不强合为一套系统 <a class="header-anchor" href="#三、辩者命题-共同响应-不强合为一套系统" aria-label="Permalink to &quot;三、辩者命题：共同响应，不强合为一套系统&quot;">​</a></h3><p>卵有毛、狗非犬、矩不方、飞鸟之景未动、日取其半等，涉及属性、名称、数量、运动与分割。</p><p>原文未逐项给出前提与证明，也未说这些命题都由一人提出。</p><p>可以帮助追问名实、标准与观察位置，但不能为求顺畅而编成唯一完整理论。</p><p>例如不断取半可以联系无限过程，却不能直接说古文已经完整建立现代极限理论。</p><h3 id="四、胜口不服心-取胜、成立与理解不是一回事" tabindex="-1">四、胜口不服心：取胜、成立与理解不是一回事 <a class="header-anchor" href="#四、胜口不服心-取胜、成立与理解不是一回事" aria-label="Permalink to &quot;四、胜口不服心：取胜、成立与理解不是一回事&quot;">​</a></h3><blockquote><p>能胜人之口，不能服人之心，辩者之囿也。</p></blockquote><p>辩说可能令对方无法继续反驳，却未带来真正理解、认可和转变。</p><p>但服心也不证明命题真实，不能以情感认同代替可靠论证。</p><p>应分别看：</p><p><strong>说法能否成立 → 对方是否理解 → 是否愿意认可 → 是否改变实践。</strong></p><p>本篇关注争胜局限，不取消必要讨论与辨别。</p><h3 id="五、多而无已-从认识万物到以异、以胜自名" tabindex="-1">五、多而无已：从认识万物到以异、以胜自名 <a class="header-anchor" href="#五、多而无已-从认识万物到以异、以胜自名" aria-label="Permalink to &quot;五、多而无已：从认识万物到以异、以胜自名&quot;">​</a></h3><p>面对天地风雨之问，惠施迅速应答，体现才力。</p><p>随后却写说而不休、多仍觉寡、益之以怪、欲以胜人为名。</p><p>问题由认识多少转向怎样使用才智：论说是否成为不断求异、自贤和胜人的活动？</p><p>不将所有创新、反常思想或辩论都定为争名；须看具体目的和关系后果。</p><h3 id="六、强于物、弱于德-外向辨说不能替代安顿" tabindex="-1">六、强于物、弱于德：外向辨说不能替代安顿 <a class="header-anchor" href="#六、强于物、弱于德-外向辨说不能替代安顿" aria-label="Permalink to &quot;六、强于物、弱于德：外向辨说不能替代安顿&quot;">​</a></h3><p>蚊虻之劳的譬喻不是否认聪明，而是从天地之道的更大尺度，反衬其忙碌与局促。</p><p>“充一尚可……”有疑难，不强据它定出一套确切阶段论。</p><p>前后较清楚的是：一端才力被不断抬高，却没有实现自身安宁。</p><h3 id="七、不能自宁-知识增长未解除追逐" tabindex="-1">七、不能自宁：知识增长未解除追逐 <a class="header-anchor" href="#七、不能自宁-知识增长未解除追逐" aria-label="Permalink to &quot;七、不能自宁：知识增长未解除追逐&quot;">​</a></h3><blockquote><p>惠施不能以此自宁，散于万物而不厌，卒以善辩为名。</p></blockquote><p>不只是知识有限，而是知识不断向外增长仍不能使人安顿。</p><p>声追响、形竞影说明所用办法可能让追逐继续发生。</p><p>与《渔父》畏影恶迹可对读：都提醒加倍重复某种办法，未必解除问题。但一段讲逃避影迹，一段讲追逐辨说，不能完全等同。</p><h3 id="八、惜才与悲叹-不只是给失败者定罪" tabindex="-1">八、惜才与悲叹：不只是给失败者定罪 <a class="header-anchor" href="#八、惜才与悲叹-不只是给失败者定罪" aria-label="Permalink to &quot;八、惜才与悲叹：不只是给失败者定罪&quot;">​</a></h3><blockquote><p>惜乎！惠施之才。</p></blockquote><p>末尾惋惜真实才力失去归处，不是只讥笑无能。</p><p>“逐万物而不反”回扣开篇百家往而不反：</p><p><strong>展开越来越多，却未返回根本、整体与自身。</strong></p><p>不要求停止研究万物，也不要求复古。要检验研究是否只服务于求异争胜，能否重新联系整体。</p><h3 id="九、庄周与惠施-都非常规-评价却不能只看形式" tabindex="-1">九、庄周与惠施：都非常规，评价却不能只看形式 <a class="header-anchor" href="#九、庄周与惠施-都非常规-评价却不能只看形式" aria-label="Permalink to &quot;九、庄周与惠施：都非常规，评价却不能只看形式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方向</th><th>庄周段</th><th>惠施段</th></tr></thead><tbody><tr><td>表达</td><td>谬悠、荒唐、诸三言</td><td>多方、历物、相应辩说</td></tr><tr><td>奇异的评价</td><td>可观、充实、不奇见</td><td>益怪、反人、求胜</td></tr><tr><td>对人关系</td><td>不傲物、与世俗处</td><td>与众不适</td></tr><tr><td>根本与万物</td><td>通本宗、应化解物</td><td>强物弱德、不能自宁</td></tr><tr><td>收束</td><td>未尽，保留解释空间</td><td>惜才、逐物不反</td></tr></tbody></table><p>这是本篇如何描写二人的对照，不证明历史惠施没有其他深刻思想，也不以奇异形式单独决定高下。</p><h3 id="本份·核心对照-4" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-4" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>才学</td><td>多方、五车</td><td>数量不自证整体</td><td>惠施毫无才力</td></tr><tr><td>历物</td><td>大一、小一、同异</td><td>尺度与分类</td><td>已有唯一现代解释</td></tr><tr><td>辩者</td><td>卵有毛等</td><td>多种反常命题</td><td>全部归惠施</td></tr><tr><td>限域</td><td>胜口不服心</td><td>取胜与理解不同</td><td>服心即真理</td></tr><tr><td>自名</td><td>欲以胜人为名</td><td>才智转向争胜</td><td>所有辩论都错误</td></tr><tr><td>德物</td><td>弱德强物</td><td>外向功用与安顿</td><td>研究万物都无意义</td></tr><tr><td>自宁</td><td>不能以此自宁</td><td>增长不解除失衡</td><td>少知道就是安宁</td></tr><tr><td>篇末</td><td>逐万物而不反</td><td>回扣总纲</td><td>反对分析、要求复古</td></tr><tr><td>惜才</td><td>惜乎惠施之才</td><td>才力与失归分看</td><td>只有嘲讽没有惋惜</td></tr></tbody></table><h3 id="本份收束-4" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-4" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>惠施段不是仅因命题奇怪而作否定，而是将才学、求异、争胜、对人关系与自宁放在一起。</p><p>真有才力，不免除整体检验；不断扩展，也不保证已找到归处。</p><p>篇末回到总纲：<strong>一端向外展开之后，是否仍能返回？</strong></p><h2 id="全篇脉络·五份阅读地图" tabindex="-1">全篇脉络·五份阅读地图 <a class="header-anchor" href="#全篇脉络·五份阅读地图" aria-label="Permalink to &quot;全篇脉络·五份阅读地图&quot;">​</a></h2>',50)),a(n,{title:"有长处，也不能以一端自足",summary:"总纲建立整体尺度，诸家评议分别辨认真实所得、实践偏向与所行限度。篇末惠施的逐物不反，再次回扣百家往而不反。"}),t[48]||(t[48]=d('<h3 id="整理说明" tabindex="-1">整理说明 <a class="header-anchor" href="#整理说明" aria-label="Permalink to &quot;整理说明&quot;">​</a></h3><p>全篇按五份处理，分份只是阅读方式：</p><ol><li>道术整体与百家分裂。</li><li>墨家与宋钘、尹文。</li><li>彭蒙、田骈、慎到与关尹、老聃。</li><li>庄周。</li><li>惠施与天下辩者。</li></ol><p>不同评议语气有明显差别，不机械地把每家都归入同一种“全错”或“只有一点对”的判决。</p><p>古人之备是理想性图景，第三人称庄周评议的作者归属与篇章形成问题，本稿不据现有材料强定。</p><h2 id="行动线与诸家评议" tabindex="-1">行动线与诸家评议 <a class="header-anchor" href="#行动线与诸家评议" aria-label="Permalink to &quot;行动线与诸家评议&quot;">​</a></h2><h4 id="总纲" tabindex="-1">总纲 <a class="header-anchor" href="#总纲" aria-label="Permalink to &quot;总纲&quot;">​</a></h4><p>诸家繁盛而自足<br> → 道术无乎不在、皆原于一<br> → 根本、圣德、礼乐、制度、养民相通<br> → 古人之备<br> → 多处典籍与方法传承<br> → 天下失序<br> → 得一察而自好<br> → 有长有用却不该不遍<br> → 各自立方、往而不反<br> → 道术之裂。</p><p>这条链是对原文结构的整理，不是历史因果已获验证的模型。</p><h4 id="诸家评议" tabindex="-1">诸家评议 <a class="header-anchor" href="#诸家评议" aria-label="Permalink to &quot;诸家评议&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对象</th><th>承接或呈现的方向</th><th>主要检验</th><th>篇内评价的界限</th></tr></thead><tbody><tr><td>墨家</td><td>节制、救急、泛爱兼利</td><td>苛苦是否适用于天下？</td><td>意是行非，同时肯定才力</td></tr><tr><td>宋尹</td><td>安民、止战、人我足养</td><td>强说与自养不足</td><td>所行止于特定范围</td></tr><tr><td>彭田慎</td><td>无私齐物、去己俱往</td><td>是否走向无知随转？</td><td>不知道，但曾有闻</td></tr><tr><td>关老</td><td>重本、取虚、柔下</td><td>是否不毁物、不削人？</td><td>博大真人，但未极</td></tr><tr><td>庄周</td><td>无形应化、三言展开</td><td>能否通本且不傲物？</td><td>高度赞许，未尽有解释空间</td></tr><tr><td>惠施辩者</td><td>多方历物、反常辨说</td><td>是否求胜而不能自宁？</td><td>惜才，批评逐物不反</td></tr></tbody></table><h4 id="首尾照应" tabindex="-1">首尾照应 <a class="header-anchor" href="#首尾照应" aria-label="Permalink to &quot;首尾照应&quot;">​</a></h4><table tabindex="0"><thead><tr><th>开篇</th><th>篇末</th></tr></thead><tbody><tr><td>得一察以自好</td><td>口谈自以为最贤</td></tr><tr><td>各有长、时有用</td><td>多方、五车、善辩之才</td></tr><tr><td>一曲不周遍</td><td>强于物而弱于德</td></tr><tr><td>百家往而不反</td><td>逐万物而不反</td></tr><tr><td>不见古人之大体</td><td>不能以此自宁</td></tr></tbody></table><p>学术结构的失联，在篇末被落实到一个人的认识与行动方式中。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h4 id="第一问-道术的整体-是否要求取消诸家差异" tabindex="-1">第一问：道术的整体，是否要求取消诸家差异？ <a class="header-anchor" href="#第一问-道术的整体-是否要求取消诸家差异" aria-label="Permalink to &quot;第一问：道术的整体，是否要求取消诸家差异？&quot;">​</a></h4><p><strong>不应仅将整体理解为所有人说一样的话。</strong></p><p>总纲承认不同人物境界、礼乐、百官、民生与典籍传承，各层有真实作用。</p><p>“皆有所长，时有所用”明确肯定局部价值。</p><p>分裂关键不是不同，而是：</p><ul><li>不承认所长之外仍有未得。</li><li>以一种方法独占全部评价。</li><li>分析与展开后不能返回整体。</li><li>将传承或身份变成自足凭据。</li></ul><p>但本篇确有理想性的统一尺度，不能完全改写成现代平等多元主义。它仍判断诸家是否与共同根本、整体实践相称。</p><p><strong>多样可以相通，一端不能自称全部。</strong></p><h4 id="第二问-为什么好的用意、真实的长处仍可能受到批评" tabindex="-1">第二问：为什么好的用意、真实的长处仍可能受到批评？ <a class="header-anchor" href="#第二问-为什么好的用意、真实的长处仍可能受到批评" aria-label="Permalink to &quot;第二问：为什么好的用意、真实的长处仍可能受到批评？&quot;">​</a></h4><p><strong>因为用意、实践、普遍承担与整体范围不是同一评价层面。</strong></p><p>墨子个人能忍苦，不证明天下都能忍；宋尹爱天下，不证明强说总能通行；去己免患，不证明无知随转是活人的实践。</p><p>柔下需要不毁物的实质，奇异文辞需要充实与不傲物，知识丰厚需要检验是否只求胜、不能自宁。</p><p>可归纳为：</p><p><strong>承接什么 → 怎样做 → 对人我造成什么 → 能否普遍承担 → 覆盖与遗漏什么。</strong></p><p>因而，可以敬重墨子的才力、惋惜惠施的才能，同时批评其方法。这不是自相矛盾，而是把评价层次分开。</p><h4 id="第三问-返回整体-是否意味着不要分析、言说与实践" tabindex="-1">第三问：返回整体，是否意味着不要分析、言说与实践？ <a class="header-anchor" href="#第三问-返回整体-是否意味着不要分析、言说与实践" aria-label="Permalink to &quot;第三问：返回整体，是否意味着不要分析、言说与实践？&quot;">​</a></h4><p><strong>不是停止展开，而是不让展开切断与根本和生活的联系。</strong></p><p>总纲本身列举典籍、法度、参验、稽决与养民；庄周评议也通过三言、应化解物呈现活的展开。</p><p>问题在：</p><ul><li>分析是否只剩割裂。</li><li>节制是否变成受苦竞赛。</li><li>救世是否忽略自身与他人的承受条件。</li><li>无己是否取消判断与承担。</li><li>言说是否仅为求异求胜。</li><li>才智是否不能帮助安顿与相处。</li></ul><p>“反”可联系回看根本、整体、人我关系与实践条件，不等于恢复所有古代制度。</p><p>本篇未给出一套现代操作程序，也未将某一评议对象无疑地确认为全部道术的封闭终点。</p><h2 id="阅读辨析与疑难校正" tabindex="-1">阅读辨析与疑难校正 <a class="header-anchor" href="#阅读辨析与疑难校正" aria-label="Permalink to &quot;阅读辨析与疑难校正&quot;">​</a></h2><h4 id="整体理想与历史叙述" tabindex="-1">整体理想与历史叙述 <a class="header-anchor" href="#整体理想与历史叙述" aria-label="Permalink to &quot;整体理想与历史叙述&quot;">​</a></h4><p>古人之备为评议提供尺度，但不能当作已经证实的古代学术全貌。</p><p>典籍、乐名、制度层数及人物传承的历史问题，需要另外查核。</p><h4 id="肯定与批评并存" tabindex="-1">肯定与批评并存 <a class="header-anchor" href="#肯定与批评并存" aria-label="Permalink to &quot;肯定与批评并存&quot;">​</a></h4><p>意是行非、曾有闻而不知道、博大而未极、才高而失归，各有不同力度。</p><p>不把“虽然”后的转折删去，也不让赞许遮住限度。</p><h4 id="关老未极与庄周未尽" tabindex="-1">关老未极与庄周未尽 <a class="header-anchor" href="#关老未极与庄周未尽" aria-label="Permalink to &quot;关老未极与庄周未尽&quot;">​</a></h4><p>未至于极明确保留未达极致；未之尽者的所指与语气更开放。</p><p>不直接当作同一句话，也不据此建立确定的诸家境界排行榜。</p><h4 id="不责是非与全篇评议" tabindex="-1">不责是非与全篇评议 <a class="header-anchor" href="#不责是非与全篇评议" aria-label="Permalink to &quot;不责是非与全篇评议&quot;">​</a></h4><p>庄周不谴是非并不意味着本篇取消评价。</p><p>可区分辨明得失与靠责斥建立自我优越，但原文没有完成所有判断情境的系统划界。</p><h4 id="奇异表达与实际内容" tabindex="-1">奇异表达与实际内容 <a class="header-anchor" href="#奇异表达与实际内容" aria-label="Permalink to &quot;奇异表达与实际内容&quot;">​</a></h4><p>庄周、惠施都有非常规表达，评价却涉及充实、关系、根本与自宁。</p><p>形式奇异既不自动为深刻，也不自动为错误。</p><h4 id="诸家评议与诸家自述" tabindex="-1">诸家评议与诸家自述 <a class="header-anchor" href="#诸家评议与诸家自述" aria-label="Permalink to &quot;诸家评议与诸家自述&quot;">​</a></h4><p>《天下》选择性地描写人物与学派，不等于他们所有著作、命题和实践的完整记录。</p><p>对具体思想史的结论，应继续与相应材料对读。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><blockquote><p>以下为现代引申，不等同于原文明言的学术制度、心理机制或实践方案。</p></blockquote><h4 id="专业知识要承认范围" tabindex="-1">专业知识要承认范围 <a class="header-anchor" href="#专业知识要承认范围" aria-label="Permalink to &quot;专业知识要承认范围&quot;">​</a></h4><p>擅长一个领域不自动有资格裁定所有问题。</p><p>保留专业价值，也明确前提、适用条件、尚未知晓的层面与协作需要。</p><h4 id="不以牺牲程度作为唯一贡献指标" tabindex="-1">不以牺牲程度作为唯一贡献指标 <a class="header-anchor" href="#不以牺牲程度作为唯一贡献指标" aria-label="Permalink to &quot;不以牺牲程度作为唯一贡献指标&quot;">​</a></h4><p>困苦可能是完成任务不得不付出的代价，却不应自动变成越苦越有德的竞赛。</p><p>应同时检验实际作用、必要性、可持续性及不同人的承受条件。</p><h4 id="助人与自养不是必然对立" tabindex="-1">助人与自养不是必然对立 <a class="header-anchor" href="#助人与自养不是必然对立" aria-label="Permalink to &quot;助人与自养不是必然对立&quot;">​</a></h4><p>真正的长期关怀需要保留行动者自身的生活、资源与恢复条件。</p><p>不以救世、工作或责任的美名免除对耗损的检验。</p><h4 id="不强作-也不能放弃承担" tabindex="-1">不强作，也不能放弃承担 <a class="header-anchor" href="#不强作-也不能放弃承担" aria-label="Permalink to &quot;不强作，也不能放弃承担&quot;">​</a></h4><p>不让私己偏好主宰，与遇事只随外力推动不同。</p><p>需要判断、回应和负责时，不能以无为或无己作为免责任的口号。</p><h4 id="尊重根本-也尊重具体人" tabindex="-1">尊重根本，也尊重具体人 <a class="header-anchor" href="#尊重根本-也尊重具体人" aria-label="Permalink to &quot;尊重根本，也尊重具体人&quot;">​</a></h4><p>精神理想、宏大理论和整体目标若转成毁物削人，便需要重新检验。</p><p>“我看得更高、更远”不成为轻慢别人具体生活的许可证。</p><h4 id="讨论不只以压倒对方为成功" tabindex="-1">讨论不只以压倒对方为成功 <a class="header-anchor" href="#讨论不只以压倒对方为成功" aria-label="Permalink to &quot;讨论不只以压倒对方为成功&quot;">​</a></h4><p>分别检验论证、理解、认可与实践效果。</p><p>对方无法继续反驳，不证明已经理解；对方愿意赞同，也不代替可靠依据。</p><h4 id="新奇观点需要说明前提" tabindex="-1">新奇观点需要说明前提 <a class="header-anchor" href="#新奇观点需要说明前提" aria-label="Permalink to &quot;新奇观点需要说明前提&quot;">​</a></h4><p>反常命题可以揭示惯常标准的局限，但应解释词义、比较尺度与推论。</p><p>不将现代重构写成古人已证明的唯一原义，也不靠奇异自证深刻。</p><h4 id="展开之后-定期回看整体" tabindex="-1">展开之后，定期回看整体 <a class="header-anchor" href="#展开之后-定期回看整体" aria-label="Permalink to &quot;展开之后，定期回看整体&quot;">​</a></h4><p>问自己：</p><ul><li>我忽略了哪些相关层面？</li><li>所用方法是否越过适用范围？</li><li>增加知识是否改善了理解和相处？</li><li>是否只剩求胜、自足和不断扩大同一种办法？</li></ul><p>这可以作为“往而能反”的现代启发，不是原文提供的机械公式。</p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关键词</th><th>阅读定位</th><th>核心问题</th></tr></thead><tbody><tr><td>方术、不可加</td><td>第一份·开篇</td><td>局部何以自足？</td></tr><tr><td>道术、一、无乎不在</td><td>第一份·根本之问</td><td>共同根本与多种展开</td></tr><tr><td>宗、精、真</td><td>第一份·人物境界</td><td>不离根本，不强排等级</td></tr><tr><td>仁义礼乐</td><td>第一份·君子</td><td>整体中的人事位置</td></tr><tr><td>法名参稽</td><td>第一份·百官</td><td>具体规范与验证</td></tr><tr><td>衣食、老弱孤寡</td><td>第一份·民生</td><td>整体是否容纳脆弱生活？</td></tr><tr><td>备、本数末度</td><td>第一份·古人之备</td><td>本末、小大精粗相通</td></tr><tr><td>典籍、旧法、散布</td><td>第一份·传承</td><td>多处保存与分裂不同</td></tr><tr><td>一察、自好、一曲</td><td>第一份·失序</td><td>所得与所限</td></tr><tr><td>内圣外王、大体</td><td>第一份·总纲收束</td><td>内外关联的整体</td></tr><tr><td>往而不反、裂</td><td>第一份与第五份</td><td>展开后能否返回？</td></tr><tr><td>备世之急、节用</td><td>第二份·墨家</td><td>救急方向与实践</td></tr><tr><td>非乐、薄葬、法式</td><td>第二份·墨家规范</td><td>情感生活与普遍承担</td></tr><tr><td>法禹、自苦为极</td><td>第二份·墨家后学</td><td>代价是否转成资格？</td></tr><tr><td>别墨、巨子</td><td>第二份·墨家分歧</td><td>共同经典为何仍分裂？</td></tr><tr><td>意与行</td><td>第二份·墨家总评</td><td>用意与方法分别评价</td></tr><tr><td>人我足养</td><td>第二份·宋尹</td><td>养人与养己</td></tr><tr><td>见侮不辱、禁攻寝兵</td><td>第二份·止争</td><td>不报复与不否认伤害</td></tr><tr><td>强聒、自为太少</td><td>第二份·实践局限</td><td>应人分寸与可持续性</td></tr><tr><td>情欲寡浅、适至是</td><td>第二份·范围</td><td>有内外方向仍有限</td></tr><tr><td>无私、齐物、无择</td><td>第三份·彭田慎</td><td>不以私己排物</td></tr><tr><td>弃知去己、不得已</td><td>第三份·慎到</td><td>不强作与无知随转</td></tr><tr><td>无知之物、生人之行</td><td>第三份·批评</td><td>免患能否代替活的实践？</td></tr><tr><td>曾有闻</td><td>第三份·总评</td><td>严厉评价仍保留所得</td></tr><tr><td>重本、太一、取虚</td><td>第三份·关老</td><td>根本与积聚</td></tr><tr><td>濡弱、空虚、不毁物</td><td>第三份·表实</td><td>姿态与实际内容</td></tr><tr><td>无居、水镜响</td><td>第三份·关尹</td><td>不固着而相应</td></tr><tr><td>徐、约、宽容、不削</td><td>第三份·老聃</td><td>不自耗、不侵人</td></tr><tr><td>博大真人、未极</td><td>第三份·收束</td><td>高评价与限度并存</td></tr><tr><td>无形、无常、连续问句</td><td>第四份·方向</td><td>不将变化匆忙定住</td></tr><tr><td>谬悠、荒唐、无端崖</td><td>第四份·言说</td><td>摆脱现代贬义</td></tr><tr><td>卮言、重言、寓言</td><td>第四份·三言</td><td>表达位置与读者</td></tr><tr><td>不傲物、不谴是非</td><td>第四份·关系</td><td>精神广大不立优越</td></tr><tr><td>无伤、可观、充实</td><td>第四份·书辞</td><td>奇异仍有实质尺度</td></tr><tr><td>本宗、应化解物、未尽</td><td>第四份·收束</td><td>根本与具体变化</td></tr><tr><td>多方、五车、历物</td><td>第五份·惠施</td><td>丰富不等于完备</td></tr><tr><td>大小、同异、名实</td><td>第五份·命题</td><td>前提与标准须说明</td></tr><tr><td>胜口、服心、辩者之囿</td><td>第五份·限域</td><td>取胜与理解不同</td></tr><tr><td>反人、胜人为名</td><td>第五份·行动</td><td>才智与争胜</td></tr><tr><td>强物弱德、不能自宁</td><td>第五份·总评</td><td>外向增长与安顿</td></tr><tr><td>惜才、形影竞走</td><td>第五份·篇末</td><td>失归与无尽追逐</td></tr></tbody></table><h2 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>核心句</th><th>所在部分</th><th>阅读提示</th></tr></thead><tbody><tr><td>皆以其有为不可加矣！</td><td>第一份</td><td>自足不只发生在无知者</td></tr><tr><td>无乎不在。</td><td>第一份</td><td>道术不被一处独占</td></tr><tr><td>圣有所生，王有所成，皆原于一。</td><td>第一份</td><td>内外作用与共同根本</td></tr><tr><td>老弱孤寡为意，皆有以养。</td><td>第一份</td><td>整体包含具体养民</td></tr><tr><td>古之人其备乎！</td><td>第一份</td><td>理想性整体尺度</td></tr><tr><td>明于本数，系于末度。</td><td>第一份</td><td>不舍末，也不忘本</td></tr><tr><td>天下多得一察焉以自好。</td><td>第一份</td><td>局部所得转成自满</td></tr><tr><td>皆有所长，时有所用。</td><td>第一份</td><td>承认各端价值</td></tr><tr><td>不该不遍，一曲之士也。</td><td>第一份</td><td>有用不能自证周遍</td></tr><tr><td>百家往而不反，必不合矣！</td><td>第一份</td><td>展开不返的分裂</td></tr><tr><td>古之道术有在于是者。</td><td>第二至第四份</td><td>先辨所承，不先全否</td></tr><tr><td>墨子虽独能任，奈天下何！</td><td>第二份</td><td>个人坚忍不代表普遍可行</td></tr><tr><td>日夜不休，以自苦为极。</td><td>第二份</td><td>劳苦由代价变成标准</td></tr><tr><td>意则是，其行则非也。</td><td>第二份</td><td>分层评价</td></tr><tr><td>人我之养，毕足而止。</td><td>第二份</td><td>养人也养己</td></tr><tr><td>强聒而不舍。</td><td>第二份</td><td>坚持仍须应人</td></tr><tr><td>其为人太多，其自为太少。</td><td>第二份</td><td>救世行动的失衡</td></tr><tr><td>其行适至是而止。</td><td>第二份</td><td>所得的边界</td></tr><tr><td>选则不遍，教则不至。</td><td>第三份</td><td>一端取舍的警惕</td></tr><tr><td>弃知去己，而缘不得已。</td><td>第三份</td><td>不强作及其限度</td></tr><tr><td>推而后行，曳而后往。</td><td>第三份</td><td>随转是否仍是生人实践？</td></tr><tr><td>概乎皆尝有闻者也。</td><td>第三份</td><td>批评不抹去所得</td></tr><tr><td>以空虚不毁万物为实。</td><td>第三份</td><td>根本须有关系实质</td></tr><tr><td>其动若水，其静若镜，其应若响。</td><td>第三份</td><td>无居而能相应</td></tr><tr><td>常宽容于物，不削于人。</td><td>第三份</td><td>不以重本伤物削人</td></tr><tr><td>虽未至于极……古之博大真人哉！</td><td>第三份</td><td>赞许仍保留尺度</td></tr><tr><td>寂漠无形，变化无常。</td><td>第四份</td><td>不固形，不等于无理</td></tr><tr><td>以卮言为曼衍，以重言为真，以寓言为广。</td><td>第四份</td><td>三种表达方式相配</td></tr><tr><td>独与天地精神往来，而不敖倪于万物。</td><td>第四份</td><td>广大与不傲物连读</td></tr><tr><td>不谴是非，以与世俗处。</td><td>第四份</td><td>不靠责斥确立优越</td></tr><tr><td>彼其充实，不可以已。</td><td>第四份</td><td>不是徒具奇异形式</td></tr><tr><td>其理不竭……未之尽者。</td><td>第四份</td><td>不轻封最终定案</td></tr><tr><td>惠施多方，其书五车。</td><td>第五份</td><td>才学数量不保证整体</td></tr><tr><td>能胜人之口，不能服人之心。</td><td>第五份</td><td>取胜与理解、转变</td></tr><tr><td>欲以胜人为名。</td><td>第五份</td><td>认识可能转成争名</td></tr><tr><td>弱于德，强于物。</td><td>第五份</td><td>外向才智与内在安顿</td></tr><tr><td>惠施不能以此自宁。</td><td>第五份</td><td>增长未解除失衡</td></tr><tr><td>惜乎！惠施之才。</td><td>第五份</td><td>惋惜才力，不只讥笑</td></tr><tr><td>逐万物而不反。</td><td>第五份</td><td>回扣开篇总纲</td></tr><tr><td>穷响以声，形与影竞走也。</td><td>第五份</td><td>办法延续追逐的问题</td></tr></tbody></table><h2 id="五份·一句话回顾" tabindex="-1">五份·一句话回顾 <a class="header-anchor" href="#五份·一句话回顾" aria-label="Permalink to &quot;五份·一句话回顾&quot;">​</a></h2><ol><li><strong>道术整体与百家分裂</strong>：古之道术「无乎不在」，一分之后就各执一隅。</li><li><strong>墨家与宋尹</strong>：救世的用意是真的，实践的限度也是真的。</li><li><strong>彭田慎与关老</strong>：随物、应物、无己各有实得，也各有所未至。</li><li><strong>庄周</strong>：三言应化，精神广大而不傲物——肯定之中仍留分寸。</li><li><strong>惠施与辩者</strong>：命题锋利而逐物不反，赢了辩驳，失了根本。</li></ol><h2 id="一句话读懂《天下》" tabindex="-1">一句话读懂《天下》 <a class="header-anchor" href="#一句话读懂《天下》" aria-label="Permalink to &quot;一句话读懂《天下》&quot;">​</a></h2><blockquote><p><strong>「道术将为天下裂。」</strong></p></blockquote><p>这句既是描述，也是告诫。作者先把「无乎不在」的整体立起来，再逐家看各得哪一隅：用意可以真诚，才能可以出众，命题可以精妙，但一旦以一隅自足，分裂就从这里开始。《天下》之所以是《庄子》的末篇，正在于它把全书的关切收在一句话上——<strong>有所长，不等于已见整体</strong>。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><h4 id="本次实际依据" tabindex="-1">本次实际依据 <a class="header-anchor" href="#本次实际依据" aria-label="Permalink to &quot;本次实际依据&quot;">​</a></h4><ul><li>《庄子·杂篇·天下》：以用户提供的分段原文及全篇原文为工作底本。</li><li>用户提供的第一、第二、第四份释义与辨析材料。</li><li>第三、第五份依据此次全篇原文补写的阅读整理。</li><li>与《列御寇》《渔父》的对读，依据此前整理材料中的相关问题。</li></ul><h4 id="后续校核可参考" tabindex="-1">后续校核可参考 <a class="header-anchor" href="#后续校核可参考" aria-label="Permalink to &quot;后续校核可参考&quot;">​</a></h4><p>以下书目可用于字词、句读及不同解释的进一步核对，本次未逐条查核或引用具体注释：</p><ul><li>郭庆藩《庄子集释》。</li><li>王先谦《庄子集解》。</li><li>陈鼓应《庄子今注今译》。</li></ul><p><strong>引用边界</strong>：保留疑难解释不等于完成版本对勘。诸家评议不直接等同诸家完整自述；现代命题重构与实践启发不作为原文确定含义。</p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>开篇先立一个整体：</p><p><strong>「古之人其备乎！配神明，醇天地，育万物，和天下。」</strong></p><p>结尾落到两个人：</p><p><strong>「惜乎！惠施之才，骀荡而不得，逐万物而不反。」</strong></p><p>从「其备」到「逐物不反」，中间隔着六家评述。于是最后可以这样问自己：</p><p><strong>我所专长的这一隅，是否正被我当成了整体？</strong></p><p><strong>我的用意是真诚的，但实践上我承认限度了吗？</strong></p><p><strong>我在讨论中，是求通，还是只求胜？</strong></p><p><strong>我有没有把「有所得」当成「不必再学」的理由？</strong></p><h2 id="全篇收束·有所长-仍有所未得" tabindex="-1">全篇收束·有所长，仍有所未得 <a class="header-anchor" href="#全篇收束·有所长-仍有所未得" aria-label="Permalink to &quot;全篇收束·有所长，仍有所未得&quot;">​</a></h2><p>《天下》以“备”建立尺度，以“裂”指出困境。</p><p><strong>备</strong>不只是知道很多，而是根本、精神、教化、制度与民生相通。</p><p><strong>裂</strong>不只是观点不同，而是各得一端便自足，不能返回整体。</p><p>诸家真实的所得值得承认，但仍需继续问：</p><blockquote><p>所承是什么？<br> 所行怎样落实？<br> 是否合乎人我生活与承受条件？<br> 所长之外，还遗漏什么？<br> 向外展开之后，能否返回？</p></blockquote><p>墨子的坚忍、宋尹的救世、慎到的去己、关老的柔下、庄周的自由言说与惠施的丰厚才学，都在不同层面接受检验。</p><p>本篇不让一种善意、一种形式、一项才能或一端认识，独自宣布整体已经完成。</p><p><strong>真正需要防止的，不是有所长，而是因有所长便不再承认自己尚有所未得。</strong></p>',118))])}}});export{L as __pageData,J as default};
